const smartUploadCategoryBase=openSmartUpload;openSmartUpload=function(project=''){smartUploadCategoryBase(project);const meta=document.querySelector('.smart-meta'),title=document.getElementById('smartTitle')?.closest('.field');if(meta&&!document.getElementById('smartCategory')){const field=document.createElement('div');field.className='field';field.innerHTML='<label>بابت / دسته مالی</label><input id="smartCategory" list="smartCategoryList" placeholder="مثلاً کرایه جرثقیل"><datalist id="smartCategoryList"><option value="خرید مصالح"><option value="خرید ابزار"><option value="خرید لوازم"><option value="کرایه جرثقیل"><option value="کرایه وانت"><option value="کرایه ابزارآلات"><option value="حمل‌ونقل"><option value="دستمزد"><option value="سوخت"></datalist>';meta.insertBefore(field,title||null)}}
function categoryFromDescription(text){const known=['کرایه جرثقیل','کرایه وانت','کرایه ابزارآلات','کرایه ابزار','خرید مصالح','خرید ابزار','خرید لوازم','حمل و نقل','حمل‌ونقل','دستمزد','سوخت','هزینه غذا','تعمیرات'];const direct=known.find(x=>text.includes(x));if(direct)return direct;const m=text.match(/(?:بابت|برای هزینه|هزینه(?:‌ی| ی)?)\s+([^،,.]+?)(?=\s+(?:برای|در)\s+پروژه|\s+به مبلغ|\s+مبلغ|\s+تومان|$)/);return m?m[1].trim():''}
const smartAnalyzeCategoryBase=analyzeSmartDocument;analyzeSmartDocument=function(){smartAnalyzeCategoryBase();const text=document.getElementById('smartDocCommand')?.value.trim()||'',category=categoryFromDescription(text),field=document.getElementById('smartCategory'),title=document.getElementById('smartTitle');if(category&&field)field.value=category;if(category&&title&&(!title.value||/^(?:فاکتور خرید|رسید پرداخت|رسید واریزی|سند مالی)$/.test(title.value)))title.value=category;updateSmartQuestions();showPendingEntities()}
