// v16: expense descriptions are complete documents even without a contractor or amount.
function expenseCategoryFromText(text){const cleaned=(text||'').replace(/[،,.]/g,' ').replace(/\s+/g,' ').trim();const known=['نگهبانی کارگاه','نگهبانی و کارگاه','نگهبانی','کرایه جرثقیل','کرایه وانت','کرایه ابزارآلات','کرایه ابزار','خرید مصالح','خرید ابزار','خرید لوازم','حمل و نقل','حمل‌ونقل','دستمزد','سوخت','هزینه غذا','تعمیرات'];const direct=known.find(x=>cleaned.includes(x));if(direct)return direct;const match=cleaned.match(/(?:هزینه(?:‌ی| ی)?|بابت)\s+(.+?)(?=\s+(?:برای\s+)?پروژه\s+|\s+به مبلغ|\s+مبلغ|\s+تومان|$)/)||cleaned.match(/((?:کرایه|جریمه|نگهبانی|خرید|دستمزد|حمل)\s*.+?)(?=\s+(?:برای\s+)?پروژه\s+|\s+به مبلغ|\s+مبلغ|\s+تومان|$)/);return match?match[1].replace(/^(?:کرد|کردِ)\s+/,'').trim():''}
const smartAnalyzeExpenseBase=analyzeSmartDocument;analyzeSmartDocument=function(){smartAnalyzeExpenseBase();const text=document.getElementById('smartDocCommand')?.value.trim()||'';if(/هزینه|کرایه|نگهبان|نگهبانی|دستمزد|خرید|فاکتور/.test(text)&&!v('smartType'))setSelectValue('smartType',/فاکتور|خرید/.test(text)?'فاکتور خرید':'سند مالی');const category=expenseCategoryFromText(text)||categoryFromDescription(text);if(category){const categoryField=document.getElementById('smartCategory'),title=document.getElementById('smartTitle');if(categoryField)categoryField.value=category;if(title&&(!title.value||/^(?:سند مالی|فاکتور خرید)$/.test(title.value)))title.value=category}updateSmartQuestions();showPendingEntities()}
