updateSmartQuestions=function(){const notes=[];if(!pendingSmartFile)notes.push('ابتدا فایل را انتخاب کن.');if(!v('smartType'))notes.push('نوع سند نامشخص است و با عنوان «سایر» ذخیره می‌شود.');if(!v('smartProject'))notes.push('پروژه نامشخص است و بعداً قابل تکمیل خواهد بود.');if(!v('smartCategory'))notes.push('شرح هزینه نامشخص است و با وضعیت «نیازمند تکمیل» ذخیره می‌شود.');const box=document.getElementById('smartQuestions');if(box)box.innerHTML=notes.length?`<strong>موارد نیازمند بررسی:</strong><ul>${notes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><small>این موارد مانع ثبت سند نیستند.</small>`:'<strong class="ready">اطلاعات اصلی آماده است؛ سند قابل ثبت است.</strong>';return pendingSmartFile?[]:['فایل را انتخاب کن']}
