function pettyCashRows(project){const tx=db.transactions.filter(x=>x.project===project),docs=db.documents.filter(x=>x.project===project);return{tx,docs}}
function openPettyCash(){const projects=db.projects.map(x=>x.name);document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="pettyCashModal"><div class="dialog"><div class="dialog-head"><h2>تنخواه پروژه</h2><button class="close" onclick="document.getElementById('pettyCashModal').remove()">×</button></div><div class="field"><label>پروژه</label><select id="pettyProject" onchange="showPettyCash(this.value)"><option value="">انتخاب کن</option>${projects.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div id="pettyCashResult"></div><div class="dialog-actions"><button class="btn primary" onclick="exportPettyCashCSV()">خروجی Excel</button><button class="btn" onclick="printPettyCash()">چاپ / PDF</button></div></div></div>`)}
function showPettyCash(project){const box=document.getElementById('pettyCashResult');if(!box||!project)return;const {tx,docs}=pettyCashRows(project),total=tx.filter(x=>x.kind==='expense').reduce((s,x)=>s+Number(x.amount||0),0);box.innerHTML=`<div class="petty-summary"><small>جمع هزینه</small><strong>${money(total)}</strong><span>${fa(tx.length)} ردیف مالی • ${fa(docs.length)} سند پیوست</span></div><div class="report-table">${tx.slice().reverse().map(x=>`<article><div><strong>${esc(x.category)}</strong><small>${esc(x.date)} • ${esc(x.party||'بدون طرف حساب')}</small></div><span class="out">${money(x.amount)}</span></article>`).join('')||empty()}</div><h3>پیوست‌ها</h3><div class="petty-docs">${docs.map(x=>`<button class="doc-open" onclick="viewDocument(${Number(x.id)})">${esc(x.name)} • ${esc(x.category||x.title||'سند')}</button>`).join('')||empty()}</div>`}
function exportPettyCashCSV(){const project=v('pettyProject');if(!project)return toast('پروژه را انتخاب کن');const {tx,docs}=pettyCashRows(project),rows=[['نوع','تاریخ','شرح','طرف حساب','مبلغ','نام پیوست'],...tx.map(x=>['ثبت مالی',x.date,x.category,x.party,x.amount,(db.documents.find(d=>Number(d.id)===Number(x.documentId))||{}).name||'']),...docs.filter(d=>!tx.some(x=>Number(x.documentId)===Number(d.id))).map(d=>['سند',d.date,d.category||d.title,d.party||'',d.amount||'',d.name])];download(`تنخواه-${project}.csv`,'\ufeff'+rows.map(r=>r.map(v=>`"${String(v||'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv')}
