function receiptLine(text,labels){const joined=labels.join('|'),same=text.match(new RegExp(`(?:${joined})\\s*[:：ـ-]?\\s*([^\\n]+)`,'i')),next=text.match(new RegExp(`(?:${joined})[^\\n]*\\n\\s*([^\\n]+)`,'i'));return(same?.[1]||next?.[1]||'').trim()}
function persianWordsNumber(text){const small={صفر:0,یک:1,دو:2,سه:3,چهار:4,پنج:5,شش:6,هفت:7,هشت:8,نه:9,ده:10,یازده:11,دوازده:12,سیزده:13,چهارده:14,پانزده:15,شانزده:16,هفده:17,هجده:18,نوزده:19,بیست:20,سی:30,چهل:40,پنجاه:50,شصت:60,هفتاد:70,هشتاد:80,نود:90,صد:100,دویست:200,سیصد:300,چهارصد:400,پانصد:500,ششصد:600,هفتصد:700,هشتصد:800,نهصد:900};let total=0,current=0;for(const token of(text||'').replace(/\u200c/g,' ').split(/\s+و\s+|\s+/).filter(Boolean)){if(small[token]!=null)current+=small[token];else if(token==='هزار'){total+=current*1000;current=0}else if(token==='میلیون'){total+=current*1000000;current=0}else if(token==='میلیارد'){total+=current*1000000000;current=0}}return total+current}
function receiptAmountToman(text){const raw=ocrDigits(text),values=[];for(const m of raw.matchAll(/([\d\s]{1,18})\s*(میلیون|هزار|میلیارد)?\s*(ریال|تومان)/g)){let value=Number(m[1].replace(/\s/g,''));if(!value)continue;if(m[2]==='هزار')value*=1000;if(m[2]==='میلیون')value*=1000000;if(m[2]==='میلیارد')value*=1000000000;if(m[3]==='ریال')value/=10;values.push(value)}for(const m of text.matchAll(/((?:صفر|یک|دو|سه|چهار|پنج|شش|هفت|هشت|نه|ده|یازده|دوازده|سیزده|چهارده|پانزده|شانزده|هفده|هجده|نوزده|بیست|سی|چهل|پنجاه|شصت|هفتاد|هشتاد|نود|صد|هزار|میلیون|میلیارد|و|\s)+)\s*(ریال|تومان)/g)){let value=persianWordsNumber(m[1]);if(m[2]==='ریال')value/=10;if(value)values.push(value)}return values.find(x=>x>=1000)||values[0]||0}
