// v22: Persian-first receipt OCR and an honest iPhone voice path.
function v22NormalizeOcr(value){
 return String(value||'').normalize('NFKC').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/[٬،]/g,',').replace(/[٫]/g,'.').replace(/[ـ]/g,'').replace(/(?<=\d)[\s,]+(?=\d)/g,'').replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim()
}
function v22FieldLine(text,labels){
 const lines=text.split(/\n/).map(x=>x.trim()).filter(Boolean),re=new RegExp(`(?:${labels.join('|')})\\s*[:：-]?\\s*(.*)`,'i');
 for(let i=0;i<lines.length;i++){const m=lines[i].match(re);if(m){const value=(m[1]||lines[i+1]||'').trim();if(value&&!labels.some(x=>value===x))return value}}
 return''
}
function v22Amount(text){
 const candidates=[];
 for(const m of text.matchAll(/(?:مبلغ|مبلغ تراکنش|جمع|برداشت|واریز|انتقال)?[^\d\n]{0,18}(\d{3,16})\s*(ریال|تومان|تومن)/g)){let value=Number(m[1]);if(!value)continue;if(m[2]==='ریال')value/=10;candidates.push(value)}
 const words=text.match(/((?:صفر|یک|دو|سه|چهار|پنج|شش|هفت|هشت|نه|ده|یازده|دوازده|سیزده|چهارده|پانزده|شانزده|هفده|هجده|نوزده|بیست|سی|چهل|پنجاه|شصت|هفتاد|هشتاد|نود|صد|دویست|سیصد|چهارصد|پانصد|ششصد|هفتصد|هشتصد|نهصد|هزار|میلیون|میلیارد|و|\s)+)\s*(ریال|تومان|تومن)/);
 if(words){let value=persianWordsNumber(words[1]);if(words[2]==='ریال')value/=10;if(value)candidates.push(value)}
 return Math.round(candidates.find(x=>x>=1000)||candidates[0]||0)
}
parseBankReceipt=function(value){
 const raw=v22NormalizeOcr(value),origin=v22FieldLine(raw,['مبدأ','مبدا','فرستنده','صاحب حساب مبدأ','از حساب']),destination=v22FieldLine(raw,['مقصد','گیرنده','صاحب حساب مقصد','به حساب']),note=v22FieldLine(raw,['شرح','بابت','یادداشت','توضیحات']),dateMatch=raw.match(/(1[34]\d{2})[\/\-.](\d{1,2})[\/\-.](\d{1,2})/)||raw.match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](1[34]\d{2})/),date=dateMatch?(dateMatch[1].length===4?`${dateMatch[1]}/${dateMatch[2].padStart(2,'0')}/${dateMatch[3].padStart(2,'0')}`:`${dateMatch[3]}/${dateMatch[2].padStart(2,'0')}/${dateMatch[1].padStart(2,'0')}`):'',amount=v22Amount(raw),category=costCategoryFromNote(note||raw),project=db.projects.find(x=>(note||raw).includes(x.name))?.name||'';
 return{origin:origin.replace(/(?:شماره|حساب|کارت)\s*[:：-]?.*$/,'').trim(),destination:destination.replace(/(?:شماره|حساب|کارت)\s*[:：-]?.*$/,'').trim(),amount,date,note,category,project,time:'',tracking:''}
}
renderReceiptFields=function(fields){
 const box=document.getElementById('smartOcrFields');if(!box)return;const items=[['مبدأ',fields.origin],['مقصد',fields.destination],['مبلغ',fields.amount?money(fields.amount):'تشخیص داده نشد'],['تاریخ',fields.date||'تشخیص داده نشد'],['شرح',fields.note||'تشخیص داده نشد']];box.innerHTML=`<strong>اطلاعات اصلی سند</strong><p class="ocr-hint">فقط موارد مهم استخراج شده‌اند؛ قبل از ثبت می‌توانی اصلاحشان کنی.</p><div>${items.map(([k,val])=>`<p><span>${k}</span><b>${esc(val||'—')}</b></p>`).join('')}</div>`
}
function v22OpenKeyboard(){const input=document.getElementById('quickText');if(!input)return;input.removeAttribute('readonly');input.focus({preventScroll:false});const end=input.value.length;try{input.setSelectionRange(end,end)}catch{}setVoiceState('کیبورد باز شد؛ میکروفن فارسی روی کیبورد آیفون را بزن.');toast('میکروفن فارسیِ خود کیبورد را بزن')}
startVoice=async function(){
 const input=document.getElementById('quickText');if(!input)return;const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
 if(!Recognition||/iPhone|iPad|iPod/i.test(navigator.userAgent||'')){v22OpenKeyboard();return}
 if(voiceListening&&voiceRecognition){voiceRecognition.stop();return}
 try{const recognition=new Recognition();voiceRecognition=recognition;recognition.lang='fa-IR';recognition.continuous=false;recognition.interimResults=true;let finalText='';recognition.onstart=()=>setVoiceState('در حال شنیدن… فارسی صحبت کن',true);recognition.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const part=e.results[i][0].transcript;if(e.results[i].isFinal)finalText+=part+' ';else interim+=part}input.value=(finalText||interim).trim()};recognition.onerror=()=>{voiceRecognition=null;v22OpenKeyboard()};recognition.onend=()=>{voiceRecognition=null;setVoiceState(input.value.trim()?'صدا به متن تبدیل شد؛ حالا تحلیل را بزن.':'متنی دریافت نشد؛ از میکروفن فارسی کیبورد استفاده کن.')};recognition.start()}catch{v22OpenKeyboard()}
}

// v23: optional secure AI backend for real Persian voice and receipt understanding.
const AI_ENDPOINT_KEY='peymanyar-ai-endpoint';
let aiRecorder=null,aiVoiceStream=null,aiVoiceChunks=[];
function aiEndpoint(){return(localStorage.getItem(AI_ENDPOINT_KEY)||'https://peymanyar-ai.mehdi-alvandi111.workers.dev').replace(/\/$/,'')}
function saveAiEndpoint(){const value=v('aiEndpointInput').replace(/\/$/,'');if(value&&!/^https:\/\//.test(value))return toast('نشانی اتصال باید با https شروع شود');if(value)localStorage.setItem(AI_ENDPOINT_KEY,value);else localStorage.removeItem(AI_ENDPOINT_KEY);toast(value?'اتصال هوش مصنوعی ذخیره شد':'اتصال هوش مصنوعی پاک شد');render()}
async function testAiEndpoint(){const endpoint=aiEndpoint();if(!endpoint)return toast('ابتدا نشانی اتصال را وارد کن');const label=document.getElementById('aiConnectionState');if(label)label.textContent='در حال بررسی…';try{const response=await fetch(`${endpoint}/health`);if(!response.ok)throw new Error();if(label)label.textContent='متصل و آماده';toast('هوش مصنوعی آماده است')}catch{if(label)label.textContent='اتصال برقرار نشد';toast('اتصال هوش مصنوعی برقرار نشد')}}
const v23SettingsBase=settings;settings=function(){const html=v23SettingsBase(),endpoint=aiEndpoint(),card=`<section class="card ai-settings"><div class="ai-settings-head"><div><h3>هوش مصنوعی فارسی</h3><p>برای خواندن دقیق سند و ضبط واقعی صدا</p></div><span id="aiConnectionState" class="pill ${endpoint?'':'paused'}">${endpoint?'تنظیم شده':'متصل نیست'}</span></div><div class="field"><label>نشانی اتصال امن</label><input id="aiEndpointInput" dir="ltr" value="${esc(endpoint)}" placeholder="https://peymanyar-ai....workers.dev"></div><div class="dialog-actions"><button class="btn primary" onclick="saveAiEndpoint()">ذخیره اتصال</button><button class="btn" onclick="testAiEndpoint()">آزمایش اتصال</button></div></section>`;return html.replace('<div class="grid-2">',card+'<div class="grid-2">')}
async function aiReceipt(file){const endpoint=aiEndpoint();if(!endpoint)throw new Error('not_configured');const form=new FormData();form.append('file',file,file.name||'receipt.jpg');const response=await fetch(`${endpoint}/receipt`,{method:'POST',body:form});if(!response.ok)throw new Error('receipt_failed');return response.json()}
async function readSmartReceiptWithAI(file){const box=document.getElementById('smartQuestions');if(box)box.innerHTML='<strong>هوش مصنوعی در حال خواندن سند فارسی است…</strong><p>مبدأ، مقصد، مبلغ، تاریخ و شرح استخراج می‌شود.</p>';try{smartReceiptFields=await aiReceipt(file);smartOcrText='';if(smartReceiptFields.destination)setSelectValue('smartPerson',smartReceiptFields.destination);if(smartReceiptFields.amount){const amount=document.getElementById('smartAmount');if(amount){amount.value=fa(smartReceiptFields.amount);amount.dispatchEvent(new Event('input',{bubbles:true}))}}if(smartReceiptFields.date){const date=document.getElementById('smartDate');if(date)date.value=smartReceiptFields.date}const command=document.getElementById('smartDocCommand');if(command&&smartReceiptFields.note)command.value=smartReceiptFields.note;const category=costCategoryFromNote(smartReceiptFields.note||'');if(category){const categoryField=document.getElementById('smartCategory');if(categoryField)categoryField.value=category;const title=document.getElementById('smartTitle');if(title)title.value=smartReceiptFields.note||category}if(!v('smartType'))setSelectValue('smartType',/واریز|دریافت/.test(smartReceiptFields.note||'')?'رسید واریزی':'رسید پرداخت');renderReceiptFields(smartReceiptFields);analyzeSmartDocument();updateSmartQuestions();toast('سند با هوش مصنوعی خوانده شد')}catch(error){toast('هوش مصنوعی متصل نیست؛ خواندن داخل گوشی اجرا شد');readSmartReceiptImage()}}
smartFileSelected=function(input){pendingSmartFile=input.files?.[0]||null;const label=document.getElementById('smartFileName');if(label&&pendingSmartFile)label.textContent=pendingSmartFile.name;analyzeSmartDocument();if(pendingSmartFile?.type.startsWith('image/')){if(aiEndpoint())readSmartReceiptWithAI(pendingSmartFile);else readSmartReceiptImage()}}
async function sendVoiceToAI(blob){const endpoint=aiEndpoint(),input=document.getElementById('quickText');if(!endpoint||!input)throw new Error('not_configured');setVoiceState('در حال تبدیل صدای فارسی به متن…',true);const ext=blob.type.includes('mp4')?'m4a':'webm',form=new FormData();form.append('file',blob,`voice.${ext}`);const response=await fetch(`${endpoint}/transcribe`,{method:'POST',body:form});if(!response.ok)throw new Error('transcription_failed');const result=await response.json();input.value=(result.text||'').trim();setVoiceState(input.value?'متن فارسی آماده شد؛ در حال تحلیل فرمان…':'صدایی تشخیص داده نشد.');if(input.value)setTimeout(parseQuick,200)}
async function startAiVoice(){if(aiRecorder?.state==='recording'){aiRecorder.stop();setVoiceState('ضبط تمام شد؛ در حال ارسال…',true);return}try{aiVoiceStream=await navigator.mediaDevices.getUserMedia({audio:true});const preferred=['audio/mp4','audio/webm;codecs=opus','audio/webm'].find(x=>MediaRecorder.isTypeSupported?.(x))||'',options=preferred?{mimeType:preferred}:undefined;aiVoiceChunks=[];aiRecorder=new MediaRecorder(aiVoiceStream,options);aiRecorder.ondataavailable=e=>{if(e.data.size)aiVoiceChunks.push(e.data)};aiRecorder.onstop=async()=>{const blob=new Blob(aiVoiceChunks,{type:aiRecorder.mimeType||'audio/webm'});aiVoiceStream?.getTracks().forEach(x=>x.stop());try{await sendVoiceToAI(blob)}catch{setVoiceState('تبدیل صدا انجام نشد؛ اتصال هوش مصنوعی را بررسی کن.');toast('خطا در تبدیل صدای فارسی')}};aiRecorder.start();setVoiceState('در حال ضبط… صحبت کن و برای پایان دوباره بزن',true)}catch{setVoiceState('اجازهٔ میکروفن داده نشد.');toast('دسترسی میکروفن را روی Allow بگذار')}}
const v23VoiceFallback=startVoice;startVoice=function(){if(aiEndpoint()&&window.MediaRecorder&&navigator.mediaDevices?.getUserMedia)return startAiVoice();return v23VoiceFallback()}

// v25: commercial workspace foundation — plans, industries, members and permissions.
const Workspace=window.PeymanyarWorkspace;
function workspaceIndustryOptions(selected){return Object.entries(Workspace.INDUSTRIES).map(([key,item])=>`<option value="${key}" ${key===selected?'selected':''}>${esc(item.name)}</option>`).join('')}
function workspacePlanOptions(selected){return Object.entries(Workspace.PLANS).map(([key,item])=>`<option value="${key}" ${key===selected?'selected':''}>${esc(item.name)}</option>`).join('')}
function workspaceRoleOptions(selected){return Object.entries(Workspace.ROLE_NAMES).map(([key,name])=>`<option value="${key}" ${key===selected?'selected':''}>${esc(name)}</option>`).join('')}
function workspaceProjectChecks(selected=[]){return db.projects.map(p=>`<label class="project-access"><input type="checkbox" name="memberProject" value="${String(p.id)}" ${selected.includes(String(p.id))?'checked':''}><span>${esc(p.name)}</span></label>`).join('')||'<small>هنوز پروژه‌ای ثبت نشده؛ عضو به همه پروژه‌های آینده دسترسی خواهد داشت.</small>'}
function workspaceSummaryCard(){const ws=db.workspace,plan=Workspace.plan(db),industry=Workspace.industry(db),member=Workspace.activeMember(db);return `<section class="card workspace-card"><div class="workspace-card-head"><div><small>فضای کاری فعال</small><h3>${esc(ws.name)}</h3><p>${esc(industry.name)} • ${esc(plan.name)}</p></div><span class="workspace-role">${esc(Workspace.roleName(member.role))}</span></div><div class="workspace-stats"><div><b>${fa(db.projects.length)}</b><small>${esc(industry.projectLabel)}</small></div><div><b>${fa(db.members.length)}</b><small>عضو</small></div><div><b>${fa(db.auditLogs.length)}</b><small>رویداد ثبت‌شده</small></div></div><div class="workspace-actions"><button class="btn primary" onclick="openBusinessSettings()">تنظیم کسب‌وکار</button><button class="btn" onclick="openMemberManager()">اعضا و دسترسی‌ها</button><button class="btn" onclick="openWorkspaceAudit()">تاریخچه فعالیت</button></div></section>`}
function openBusinessSettings(){const ws=db.workspace;document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="workspaceModal" onclick="if(event.target===this)closeWorkspaceModal()"><div class="dialog" role="dialog" aria-modal="true"><div class="dialog-head"><div><h2>تنظیم کسب‌وکار</h2><small>یک هسته، متناسب با نوع فعالیت و اندازه تیم</small></div><button class="close" onclick="closeWorkspaceModal()">×</button></div><div class="form-grid">${field('نام شرکت یا دفتر',`<input id="workspaceName" value="${esc(ws.name)}">`)}${field('نوع فعالیت',`<select id="workspaceIndustry">${workspaceIndustryOptions(ws.industry)}</select>`)}${field('پلن',`<select id="workspacePlan">${workspacePlanOptions(ws.plan)}</select>`)}<div class="field full"><div class="plan-explainer"><strong>حرفه‌ای</strong><span>برای فرد و تیم کوچک؛ حداکثر ۳ عضو</span><strong>سازمانی</strong><span>تیم‌های چندنقشی، تأییدها و کنترل پرتفوی پروژه‌ها</span></div></div></div><div class="dialog-actions"><button class="btn primary" onclick="saveBusinessSettings()">ذخیره تنظیمات</button><button class="btn" onclick="closeWorkspaceModal()">انصراف</button></div></div></div>`)}
function saveBusinessSettings(){const oldPlan=db.workspace.plan;Workspace.updateWorkspace(db,{name:v('workspaceName'),industry:v('workspaceIndustry'),plan:v('workspacePlan')});save();closeWorkspaceModal();toast(oldPlan!==db.workspace.plan?'پلن و ساختار کسب‌وکار به‌روزرسانی شد':'تنظیمات کسب‌وکار ذخیره شد');render()}
function closeWorkspaceModal(){document.getElementById('workspaceModal')?.remove()}
function memberRows(){return db.members.map(m=>`<article class="member-row"><div class="member-avatar">${esc((m.name||'؟').slice(0,1))}</div><div class="member-info"><strong>${esc(m.name)}</strong><small>${esc(Workspace.roleName(m.role))} • ${m.projectIds?.length?fa(m.projectIds.length)+' پروژه':'همه پروژه‌ها'} • ${m.status==='active'?'فعال':'دعوت‌نشده'}</small></div>${m.role==='owner'?'<span class="pill">مالک</span>':`<button class="member-remove" onclick="removeWorkspaceMember('${m.id}')">حذف</button>`}</article>`).join('')}
function openMemberManager(){const plan=Workspace.plan(db),atLimit=db.members.length>=plan.maxMembers;document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="workspaceModal" onclick="if(event.target===this)closeWorkspaceModal()"><div class="dialog member-dialog" role="dialog" aria-modal="true"><div class="dialog-head"><div><h2>اعضا و دسترسی‌ها</h2><small>${esc(plan.name)} • ${plan.maxMembers===999?'بدون محدودیت عملی':`حداکثر ${fa(plan.maxMembers)} عضو`}</small></div><button class="close" onclick="closeWorkspaceModal()">×</button></div><div class="member-list">${memberRows()}</div><div class="member-add ${atLimit?'is-locked':''}"><h3>افزودن عضو</h3>${atLimit?'<p class="upgrade-note">ظرفیت پلن حرفه‌ای تکمیل است. برای تیم بزرگ‌تر، پلن سازمانی را فعال کن.</p>':`<div class="form-grid">${field('نام و نام خانوادگی','<input id="memberName">')}${field('شماره موبایل','<input id="memberPhone" inputmode="tel" dir="ltr">')}${field('ایمیل','<input id="memberEmail" inputmode="email" dir="ltr">')}${field('نقش',`<select id="memberRole">${workspaceRoleOptions('site_supervisor')}</select>`)}<div class="field full"><label>پروژه‌های قابل دسترسی</label><div class="project-access-list">${workspaceProjectChecks()}</div><small>اگر پروژه‌ای انتخاب نشود، دسترسی نقش برای همه پروژه‌ها اعمال می‌شود.</small></div></div><button class="btn primary full-action" onclick="addWorkspaceMember()">ایجاد دعوت‌نامه عضو</button>`}</div><p class="cloud-note">دعوت پیامکی/ایمیلی پس از فعال‌شدن حساب ابری ارسال می‌شود؛ فعلاً ساختار و دسترسی عضو ذخیره می‌گردد.</p></div></div>`)}
function addWorkspaceMember(){try{const projectIds=[...document.querySelectorAll('input[name="memberProject"]:checked')].map(x=>x.value);Workspace.addMember(db,{name:v('memberName'),phone:v('memberPhone'),email:v('memberEmail'),role:v('memberRole'),projectIds});save();closeWorkspaceModal();toast('عضو و سطح دسترسی او ثبت شد');render();openMemberManager()}catch(error){toast(error.message==='plan_member_limit'?'ظرفیت این پلن تکمیل است':'نام عضو را وارد کن')}}
