function voiceServiceError(error){const detail=String(error?.message||error||'').slice(0,180);if(detail==='health_failed')return'اتصال به سرویس برقرار نشد؛ اینترنت را بررسی کن.';if(detail==='empty_audio')return'فایل صوتی خالی است؛ دوباره ضبط کن.';if(detail==='input_missing')return'صفحهٔ فرمان بسته شده است؛ دوباره آن را باز کن.';if(/401|403|invalid_api_key|authentication|unauthorized/i.test(detail))return'کلید سرویس تبدیل صدا معتبر نیست (۴۰۱/۴۰۳).';if(/429|rate_limit|quota/i.test(detail))return'سرویس تبدیل صدا شلوغ است یا سهمیه تمام شده (۴۲۹).';if(/400|422|invalid.*(audio|file)|unsupported|corrupt/i.test(detail))return`سرویس فایل ضبط‌شده را نپذیرفت: ${detail}`;if(/502|503|504|500|timeout/i.test(detail))return`سرویس پاسخ نداد: ${detail}`;if(error instanceof TypeError)return'ارسال صدا به سرور برقرار نشد؛ اتصال اینترنت یا مرورگر را بررسی کن.';return`خطای تبدیل صدا: ${detail||'پاسخ نامشخص از سرور'}`}
