removeDocument=function(id){const doc=db.documents.find(x=>String(x.id)===String(id));if(!doc)return;const linked=db.transactions.filter(x=>String(x.documentId)===String(id));if(!confirm(`سند «${doc.name}» حذف شود؟${linked.length?' ثبت مالی باقی می‌ماند و دوباره بدون پیوست نشان داده می‌شود.':''}`))return;db.documents=db.documents.filter(x=>String(x.id)!==String(id));linked.forEach(x=>{x.documentId=null});deleteStoredFile(id);save();toast('سند حذف شد؛ ثبت مالی باقی ماند');render()};
