const v31ParseQuickBase=parseQuick;
parseQuick=function(){if(document.getElementById('bulkCashModal'))return reviewBulkCash();return v31ParseQuickBase()};
// v32: keep voice registration editable; a missing specialty never blocks saving a person.
const v32ParseQuickBase=parseQuick;
parseQuick=function(){
 const input=document.getElementById('quickText'),box=document.getElementById('parsedResult');
 if(!input||!box||document.getElementById('bulkCashModal'))return v32ParseQuickBase();
 const candidate=PeymanyarCommand.parse(input.value.trim(),db,todayFa());
 if(candidate.intent!=='person_create')return v32ParseQuickBase();
 const plan=v21SmartPlan(input.value.trim());window.v21Plan=plan;window.parsedCommand=candidate;
 box.innerHTML=`<div class="parsed smart-plan"><div class="command-title"><strong>پیش‌نویس قابل ویرایش</strong><span class="command-badge">تعریف پیمانکار یا نیرو</span></div><div class="smart-plan-grid">${field('نام شخص',`<input id="spParty" value="${esc(candidate.name)}" placeholder="نام شخص را وارد کن">`)}${field('تخصص / نوع کار',`<input id="spRole" value="${esc(candidate.role)}" placeholder="اگر نامشخص است، بعداً تکمیل کن">`)}${field('پروژه',`<input id="spProject" list="spProjects" value="${esc(candidate.project||plan.project||'')}" placeholder="اختیاری"><datalist id="spProjects">${v21PlanOptions(db.projects.map(x=>x.name),candidate.project||plan.project||'')}</datalist>`)}</div><p class="creation-summary">نام و تخصص را پیش از ثبت بررسی کن؛ تخصص را می‌توانی بعداً هم تکمیل کنی.</p><button class="btn primary full-action" onclick="confirmSmartPlan()">تأیید و ثبت شخص</button></div>`;
};
const v32CompletionActionBase=completionAction;
completionAction=function(id){const task=completionOpen().find(x=>String(x.id)===String(id));if(task?.type!=='person.role')return v32CompletionActionBase(id);const person=db.people.find(x=>String(x.id)===String(task.entityId));if(!person)return;document.getElementById('completionInbox')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="roleCompletion" onclick="if(event.target===this)this.remove()"><div class="dialog"><div class="dialog-head"><h2>تکمیل تخصص ${esc(person.name)}</h2><button class="close" onclick="document.getElementById('roleCompletion').remove()">×</button></div>${field('تخصص / نوع کار',`<input id="roleCompletionInput" value="${esc(person.role==='تخصص ثبت نشده'?'':person.role)}" placeholder="مثلاً نصاب درب اتاق">`)}<button class="btn primary" onclick="saveCompletedRole('${esc(task.id)}')">ذخیره تخصص</button></div></div>`)};
function saveCompletedRole(id){const task=completionOpen().find(x=>String(x.id)===String(id)),person=db.people.find(x=>String(x.id)===String(task?.entityId)),role=v('roleCompletionInput');if(!person||!role)return toast('تخصص را وارد کن');person.role=role;task.status='done';task.resolvedAt=new Date().toISOString();save();document.getElementById('roleCompletion')?.remove();render();toast('تخصص ثبت شد')}

// v34: contract work belongs in the person's file. A draft is never a signed contract.
const contractPerson=(id)=>db.people.find(x=>Number(x.id)===Number(id));
const contractsForPerson=(person)=>db.contracts.filter(x=>x.party===person.name);
const signedContractFor=(person)=>contractsForPerson(person).some(x=>(!person.project||x.project===person.project)&&x.status==='امضاشده'&&x.documentId&&db.documents.some(d=>String(d.id)===String(x.documentId)));
const v34CompletionOpenBase=completionOpen;
completionOpen=function(){const rows=v34CompletionOpenBase().filter(x=>x.type!=='person.contract');for(const person of db.people){if(!signedContractFor(person))rows.push({id:`person-contract-${person.id}`,type:'person.contract',entityId:person.id,project:person.project||'',title:`قرارداد امضاشده ${person.name} ثبت نشده`,status:'open'})}return rows};
const v34CompletionTaskRowBase=completionTaskRow;
completionTaskRow=function(task){if(!['person.details','person.contract','person.role'].includes(task.type))return v34CompletionTaskRowBase(task);const person=contractPerson(task.entityId);if(!person)return'';const id=Number(person.id),contract=task.type==='person.contract';return `<article class="completion-row"><span class="completion-kind">${contract?'▤':'♙'}</span><div><strong>${esc(task.title)}</strong><small>${esc(task.project||'پرونده شخصی')}</small></div><button onclick="openPerson(${id})">باز کردن پرونده</button></article>`};
const v34CompletionActionBase=completionAction;
completionAction=function(id){const task=completionOpen().find(x=>String(x.id)===String(id));if(task&&['person.details','person.contract'].includes(task.type)){document.getElementById('completionInbox')?.remove();return openPerson(Number(task.entityId))}return v34CompletionActionBase(id)};
const v34ResolveCompletionTaskBase=resolveCompletionTask;
resolveCompletionTask=function(id){const task=completionOpen().find(x=>String(x.id)===String(id));if(task&&['person.details','person.contract','person.role'].includes(task.type))return completionAction(id);return v34ResolveCompletionTaskBase(id)};
const v34PersonDetailBase=personDetail;
personDetail=function(){const person=contractPerson(selectedPersonId);if(!person)return v34PersonDetailBase();const html=v34PersonDetailBase(),contracts=contractsForPerson(person),id=Number(person.id);const profile=`<section class="detail-section contract-panel"><h3>مشخصات پیمانکار</h3><p>${esc(person.phone||'شماره تماس ثبت نشده')} • ${esc(person.nationalId||'کد ملی ثبت نشده')}<br>${esc(person.address||'آدرس ثبت نشده')}</p><button class="btn" onclick="openPersonIdentity(${id})">ویرایش مشخصات</button></section>`;const actions=`<div class="contract-actions"><button class="btn primary" onclick="openContractBuilder(${id})">＋ ساخت پیش‌نویس قرارداد</button><button class="btn" onclick="openSignedContractUpload(${id})">＋ آپلود قرارداد امضاشده</button></div>${contracts.length?'':`<p class="contract-empty">هنوز قراردادی برای ${esc(person.name)} ثبت نشده است.</p>`}`;const oldHeading='<section class="detail-section"><h3>قراردادها</h3>';let result=html.replace(oldHeading,profile+oldHeading+actions);const matching=contracts.filter(x=>x.templateKey||x.documentId);if(matching.length)result=result.replace('<section class="detail-section"><h3>ریز حساب</h3>',`<section class="detail-section contract-panel"><h3>پیش‌نویس‌ها و پیوست‌ها</h3>${matching.map(x=>`<div class="contract-item"><strong>${esc(x.title)}</strong><small>${esc(x.status)} • ${esc(x.date||'تاریخ ثبت نشده')}</small><div class="contract-actions">${x.templateKey?`<button class="btn" onclick="printContractDraft(${Number(x.id)})">چاپ / ذخیره PDF</button>`:''}${x.documentId?`<button class="btn" onclick="viewDocument(${Number(x.documentId)})">مشاهده امضاشده</button>`:`<button class="btn" onclick="openSignedContractUpload(${id},${Number(x.id)})">بارگذاری امضاشده</button>`}</div></div>`).join('')}</section><section class="detail-section"><h3>ریز حساب</h3>`);return result};
function openPersonIdentity(id){const person=contractPerson(id);if(!person)return;document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="personIdentityModal"><div class="dialog"><div class="dialog-head"><h2>مشخصات ${esc(person.name)}</h2><button class="close" onclick="document.getElementById('personIdentityModal').remove()">×</button></div><div class="form-grid">${field('کد ملی',`<input id="personNationalId" inputmode="numeric" value="${esc(person.nationalId||'')}">`)}${field('شماره تماس',`<input id="personPhone" inputmode="tel" value="${esc(person.phone||'')}">`)}${field('آدرس',`<textarea id="personAddress">${esc(person.address||'')}</textarea>`,'full')}</div><button class="btn primary" onclick="savePersonIdentity(${Number(id)})">ذخیره مشخصات</button></div></div>`)}
function savePersonIdentity(id){const person=contractPerson(id);if(!person)return;person.nationalId=v('personNationalId');person.phone=v('personPhone');person.address=v('personAddress');if(person.nationalId&&person.phone&&person.address)db.completionTasks.filter(t=>t.type==='person.details'&&String(t.entityId)===String(id)).forEach(t=>t.status='done');save();document.getElementById('personIdentityModal')?.remove();render();toast('مشخصات ذخیره شد')}
function contractTemplateOptions(role){return /کابینت|نجار|چوب/.test(role||'')?{key:'cabinet',title:'قرارداد نصب کابینت',scope:'نصب، تراز و رگلاژ کابینت‌ها مطابق نقشه و فهرست اقلام پیوست؛ تحویل پس از بازدید و رفع ایرادهای ثبت‌شده.'}:{key:'general',title:`قرارداد اجرای ${role||'کار پیمانکاری'}`,scope:'اجرای عملیات موضوع توافق مطابق نقشه‌ها، مشخصات فنی و فهرست کارهای پیوست؛ تحویل پس از بازدید و رفع ایرادهای ثبت‌شده.'}}
function openContractBuilder(id){const person=contractPerson(id);if(!person)return;const issuer=db.contractIssuer||{},template=contractTemplateOptions(person.role),project=person.project||person.projects?.[0]||'';document.getElementById('contractBuilder')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="contractBuilder"><div class="dialog contract-builder"><div class="dialog-head"><h2>پیش‌نویس قرارداد ${esc(person.name)}</h2><button class="close" onclick="document.getElementById('contractBuilder').remove()">×</button></div><p class="contract-disclaimer">این متن نمونهٔ قابل ویرایش است؛ پیش از امضا، مبلغ، تعهدات، بیمه و شرایط پروژه را با مشاور حقوقی بررسی کنید.</p><div class="form-grid">${field('عنوان',`<input id="ctTitle" value="${esc(template.title)}">`)}${field('پروژه',`<input id="ctProject" value="${esc(project)}">`)}${field('نام واگذارنده (برای بعد ذخیره می‌شود)',`<input id="ctIssuer" value="${esc(issuer.name||'')}">`)}${field('کد ملی واگذارنده',`<input id="ctIssuerNational" inputmode="numeric" value="${esc(issuer.nationalId||'')}">`)}${field('تلفن واگذارنده',`<input id="ctIssuerPhone" inputmode="tel" value="${esc(issuer.phone||'')}">`)}${field('آدرس واگذارنده',`<input id="ctIssuerAddress" value="${esc(issuer.address||'')}">`)}${field('نام پیمانکار',`<input id="ctPersonName" value="${esc(person.name)}">`)}${field('کد ملی پیمانکار',`<input id="ctNational" inputmode="numeric" value="${esc(person.nationalId||'')}">`)}${field('تلفن پیمانکار',`<input id="ctPhone" inputmode="tel" value="${esc(person.phone||'')}">`)}${field('آدرس پیمانکار',`<input id="ctAddress" value="${esc(person.address||'')}">`)}${field('تاریخ شمسی',`<input id="ctDate" value="${esc(todayFa())}">`)}${field('مبلغ توافق‌شده، تومان',`<input id="ctAmount" inputmode="numeric" placeholder="پس از توافق وارد کن">`)}${field('موضوع و محدوده دقیق کار',`<textarea id="ctScope">${esc(template.scope)}</textarea>`,'full')}${field('مسئولیت تأمین مصالح و ابزار',`<textarea id="ctMaterials" placeholder="چه کسی کدام اقلام را تهیه می‌کند؟"></textarea>`,'full')}${field('زمان‌بندی و محل تحویل',`<textarea id="ctSchedule" placeholder="تاریخ شروع، مدت، مراحل و محل دقیق"></textarea>`,'full')}${field('شیوه پرداخت، کسورات و تضمین',`<textarea id="ctPayment" placeholder="مراحل پرداخت و شرایط تسویه را مشخص کن"></textarea>`,'full')}${field('کیفیت، تحویل، رفع نقص و ایمنی',`<textarea id="ctQuality" placeholder="استاندارد اجرا، تحویل، مسئولیت ایمنی و بیمه را متناسب با پروژه بنویس"></textarea>`,'full')}${field('حل اختلاف و شرایط تغییر/فسخ',`<textarea id="ctDispute" placeholder="روش حل اختلاف و شرایط تغییر یا خاتمه قرارداد"></textarea>`,'full')}</div><div class="contract-actions"><button class="btn primary" onclick="saveContractDraft(${Number(id)},'${template.key}')">ذخیره پیش‌نویس</button><button class="btn" onclick="document.getElementById('contractBuilder').remove()">انصراف</button></div></div></div>`)}
function saveContractDraft(id,key){const person=contractPerson(id),title=v('ctTitle'),project=v('ctProject'),issuer=v('ctIssuer'),contractor=v('ctPersonName'),scope=v('ctScope');if(!person||!title||!project||!issuer||!contractor||!scope)return toast('نام طرفین، پروژه، عنوان و موضوع کار را وارد کن');if(contractor!==person.name)return toast('برای تغییر نام پیمانکار، ابتدا پرونده شخص را اصلاح کن');const fields={issuer,issuerNationalId:v('ctIssuerNational'),issuerPhone:v('ctIssuerPhone'),issuerAddress:v('ctIssuerAddress'),contractorNationalId:v('ctNational'),contractorPhone:v('ctPhone'),contractorAddress:v('ctAddress'),scope,materials:v('ctMaterials'),schedule:v('ctSchedule'),payment:v('ctPayment'),quality:v('ctQuality'),dispute:v('ctDispute')},contract={id:uid(),title,project,party:person.name,amount:n('ctAmount'),date:v('ctDate')||todayFa(),status:'پیش‌نویس',templateKey:key,fields};db.contractIssuer={name:issuer,nationalId:fields.issuerNationalId,phone:fields.issuerPhone,address:fields.issuerAddress};Object.assign(person,{nationalId:fields.contractorNationalId,phone:fields.contractorPhone,address:fields.contractorAddress});db.contracts.push(contract);save();document.getElementById('contractBuilder')?.remove();render();toast('پیش‌نویس ذخیره شد؛ برای امضا چاپ یا PDF بگیر')}
function printContractDraft(id){const c=db.contracts.find(x=>Number(x.id)===Number(id));if(!c?.templateKey)return toast('پیش‌نویس پیدا نشد');const f=c.fields||{},w=window.open('','_blank');if(!w)return toast('اجازه باز شدن پنجره چاپ را فعال کن');const row=(heading,value)=>`<section><h3>${esc(heading)}</h3><p>${esc(value||'—')}</p></section>`;w.document.write(`<html lang="fa" dir="rtl"><meta charset="utf-8"><title>${esc(c.title)}</title><style>body{font-family:Tahoma,Arial,sans-serif;line-height:2;max-width:800px;margin:35px auto;padding:20px;color:#222}h1{text-align:center}h3{margin:18px 0 3px;font-size:16px}p{margin:0;white-space:pre-wrap}.warning{color:#a14235}.sign{display:flex;justify-content:space-between;margin-top:60px}section{break-inside:avoid}@page{size:A4;margin:18mm}</style><body><h1>${esc(c.title)}</h1><p class="warning">پیش‌نویس قابل بررسی؛ پیش از امضا مفاد و قوانین مرتبط بررسی شود.</p>${row('طرفین',`واگذارنده: ${f.issuer||'—'} | کد ملی: ${f.issuerNationalId||'—'} | تلفن: ${f.issuerPhone||'—'} | آدرس: ${f.issuerAddress||'—'}\nپیمانکار: ${c.party} | کد ملی: ${f.contractorNationalId||'—'} | تلفن: ${f.contractorPhone||'—'} | آدرس: ${f.contractorAddress||'—'}`)}${row('پروژه و تاریخ',`${c.project} | ${c.date}`)}${row('موضوع و محدوده',f.scope)}${row('مصالح و ابزار',f.materials)}${row('مدت و تحویل',f.schedule)}${row('مبلغ و پرداخت',`${c.amount?money(c.amount):'مبلغ تعیین نشده'}\n${f.payment||''}`)}${row('کیفیت، رفع نقص، ایمنی و بیمه',f.quality)}${row('تغییر، خاتمه و حل اختلاف',f.dispute)}<div class="sign"><div>نام، تاریخ و امضای واگذارنده:<br><br>....................</div><div>نام، تاریخ و امضای پیمانکار:<br><br>....................</div></div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function openSignedContractUpload(personId,contractId=0){const person=contractPerson(personId);if(!person)return;document.getElementById('signedContractModal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="signedContractModal"><div class="dialog"><div class="dialog-head"><h2>آپلود قرارداد امضاشده ${esc(person.name)}</h2><button class="close" onclick="document.getElementById('signedContractModal').remove()">×</button></div><p>فایل فقط روی همین دستگاه بایگانی می‌شود. از اطلاعات برنامه نیز نسخهٔ پشتیبان بگیر.</p><div class="form-grid">${field('فایل عکس یا PDF',`<input id="signedContractFile" type="file" accept="image/*,.pdf,application/pdf">`,'full')}${field('عنوان قرارداد',`<input id="signedContractTitle" value="${esc(db.contracts.find(x=>Number(x.id)===Number(contractId))?.title||'قرارداد '+(person.role||'پیمانکاری'))}">`)}${field('پروژه',`<input id="signedContractProject" value="${esc(person.project||'')}">`)}${field('تاریخ شمسی',`<input id="signedContractDate" value="${esc(todayFa())}">`)}${field('مبلغ قرارداد، تومان',`<input id="signedContractAmount" inputmode="numeric" value="${esc(db.contracts.find(x=>Number(x.id)===Number(contractId))?.amount||'')}">`)}</div><button class="btn primary" onclick="saveSignedContract(${Number(personId)},${Number(contractId)})">ثبت و اتصال فایل</button></div></div>`)}
async function saveSignedContract(personId,contractId){const person=contractPerson(personId),file=document.getElementById('signedContractFile')?.files?.[0],title=v('signedContractTitle'),project=v('signedContractProject');if(!person||!file||!title||!project)return toast('فایل، عنوان و پروژه را مشخص کن');const permitted=file.type.startsWith('image/')||file.type==='application/pdf'||/\.pdf$/i.test(file.name);if(!permitted)return toast('فقط تصویر یا PDF قرارداد را انتخاب کن');const documentId=uid();try{await storeFile(documentId,file)}catch{return toast('فایل روی دستگاه ذخیره نشد؛ دوباره تلاش کن')};memoryFiles.set(documentId,{id:documentId,blob:file,type:file.type,name:file.name});const contract=db.contracts.find(x=>Number(x.id)===Number(contractId)&&x.party===person.name);const amount=n('signedContractAmount'),date=v('signedContractDate')||todayFa();db.documents.unshift({id:documentId,name:file.name,title,project,party:person.name,docType:'قرارداد پیمانکار',date,amount,size:`${Math.max(1,Math.round(file.size/1024))} KB`,type:file.type,status:'کامل',contractId:contract?.id||null});if(contract){Object.assign(contract,{title,project,amount,date,documentId,status:'امضاشده'})}else{const created={id:uid(),title,project,party:person.name,amount,date,documentId,status:'امضاشده'};db.contracts.push(created);db.documents[0].contractId=created.id}save();document.getElementById('signedContractModal')?.remove();render();toast('فایل امضاشده به پرونده پیمانکار پیوست شد')}

// v35: shared editable clauses and trade-specific measured work, with identity fields distinct from money.
let editingContractId=0;
function contractItemRow(item={}){return `<div class="contract-rate-row"><input class="rate-name" aria-label="شرح کار" placeholder="شرح کار" value="${esc(item.name||'')}"><input class="rate-unit" aria-label="واحد" placeholder="واحد" value="${esc(item.unit||'عدد')}"><input class="rate-quantity" aria-label="مقدار" inputmode="decimal" placeholder="مقدار" value="${esc(item.quantity||'')}" oninput="refreshContractTotal()"><input class="rate-price" data-money inputmode="numeric" aria-label="نرخ واحد تومان" placeholder="نرخ واحد تومان" value="${item.rate?fa(item.rate):''}" oninput="refreshContractTotal()"><button type="button" aria-label="حذف ردیف" onclick="this.closest('.contract-rate-row').remove();refreshContractTotal()">×</button></div>`}
function identityDigits(value){return normalizeDigits(String(value||'')).replace(/[^0-9]/g,'').slice(0,10)}
const v35SavePersonIdentityBase=savePersonIdentity;
savePersonIdentity=function(id){const el=document.getElementById('personNationalId');if(el)el.value=identityDigits(el.value);return v35SavePersonIdentityBase(id)};
function contractRateItems(){return [...document.querySelectorAll('#contractBuilder .contract-rate-row')].map(row=>({name:row.querySelector('.rate-name').value.trim(),unit:row.querySelector('.rate-unit').value.trim(),quantity:PeymanyarContracts.number(row.querySelector('.rate-quantity').value),rate:PeymanyarContracts.number(row.querySelector('.rate-price').value)})).filter(x=>x.name)}
function refreshContractTotal(){const total=PeymanyarContracts.total(contractRateItems()),label=document.getElementById('contractItemTotal'),amount=document.getElementById('ctAmount');if(label)label.textContent=`جمع ردیف‌ها: ${money(total)}`;if(amount&&total>0)amount.value=fa(total)}
