function editContractDraft(contractId){const contract=db.contracts.find(x=>Number(x.id)===Number(contractId)&&x.status==='پیش‌نویس');if(!contract)return toast('فقط پیش‌نویس قابل ویرایش است');const person=db.people.find(x=>x.name===contract.party);if(!person)return;openContractBuilder(person.id);editingContractId=contract.id;const set=(id,value)=>{const el=document.getElementById(id);if(el)el.value=String(value||'')},f=contract.fields||{};for(const [id,value] of Object.entries({ctTitle:contract.title,ctProject:contract.project,ctDate:contract.date,ctAmount:contract.amount?fa(contract.amount):'',ctIssuer:f.issuer,ctIssuerNational:f.issuerNationalId,ctIssuerPhone:f.issuerPhone,ctIssuerAddress:f.issuerAddress,ctNational:f.contractorNationalId,ctPhone:f.contractorPhone,ctAddress:f.contractorAddress,ctScope:f.scope,ctMaterials:f.materials,ctSchedule:f.schedule,ctPayment:f.payment,ctQuality:f.quality,ctDispute:f.dispute}))set(id,value);if(contract.items?.length){document.getElementById('contractItems').innerHTML=contract.items.map(contractItemRow).join('');refreshContractTotal()}if(contract.clauses?.length)document.querySelectorAll('#contractBuilder .shared-clause').forEach((el,i)=>el.value=contract.clauses[i]?.body||'');document.querySelector('#contractBuilder .dialog-head h2').textContent='ویرایش پیش‌نویس قرارداد'}
