function openBulkCash(project=''){document.getElementById('bulkCashModal')?.remove();window.bulkCashDraft=null;document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="bulkCashModal" onclick="if(event.target===this)this.remove()"><div class="dialog bulk-cash-dialog"><div class="dialog-head"><h2>ثبت گروهی تنخواه و پرداخت‌ها</h2><button class="close" onclick="document.getElementById('bulkCashModal').remove()">×</button></div><p>هر پرداخت یا دریافت را در یک خط بگو یا بنویس. تاریخ هر خط جداگانه خوانده می‌شود.</p><div class="field"><label>پروژه پیش‌فرض (اختیاری)</label><select id="bulkDefaultProject"><option value="">از متن هر خط تشخیص بده</option>${db.projects.map(x=>`<option value="${esc(x.name)}" ${x.name===project?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="bulk-voice"><button type="button" id="voiceBtn" class="mic-btn" onclick="startVoice()">🎙</button><span id="voiceStatus">برای گفتن چند مورد، بین موارد بگو «سپس»؛ یا هر مورد را در یک خط بنویس.</span></div><textarea id="quickText" class="universal-text" rows="6" placeholder="سه روز پیش یک میلیون تومان بابت نگهبانی پروژه آرشام پرداخت شد&#10;دیروز دو میلیون تومان کرایه وانت پروژه آرشام پرداخت شد"></textarea><div class="dialog-actions"><button class="btn primary" onclick="reviewBulkCash()">بررسی فهرست</button></div><div id="bulkReview"></div></div></div>`)}
function splitBulkCash(text){return String(text||'').split(/\n+|\s*؛\s*|\s+(?:سپس|بعدش|بعد از آن)\s+/).map(x=>x.trim()).filter(Boolean)}
function bulkKey(row){return[normalizedProjectName(row.project),normalizeDateValue(row.date),Number(row.amount),row.kind].join('|')}
function reviewBulkCash(){const box=document.getElementById('bulkReview');if(!box)return;const lines=splitBulkCash(document.getElementById('quickText').value);if(!lines.length){box.innerHTML='<p class="bulk-error">حداقل یک ردیف بگو یا بنویس.</p>';return}const defaultProject=v('bulkDefaultProject'),seen=new Set(),rows=lines.map((text,index)=>{const plan=v21SmartPlan(text),project=plan.project||defaultProject,amount=plan.amount||PeymanyarCommand.amountOf(text),date=PeymanyarCommand.dateInfo(text,todayFa()),row={index,text,project,amount,date:date.date,dateExplicit:date.explicit,kind:plan.kind||'expense',party:plan.party||'',category:plan.category||'هزینه عمومی',valid:plan.intent==='transaction_create'&&amount>0&&!!project};row.duplicate=row.valid&&(seen.has(bulkKey(row))||db.transactions.some(tx=>bulkKey(tx)===bulkKey(row)));if(row.valid)seen.add(bulkKey(row));return row});window.bulkCashDraft=rows;box.innerHTML=`<div class="bulk-summary">${fa(rows.length)} ردیف شناسایی شد؛ موارد مشابه خودکار انتخاب نشده‌اند.</div>${rows.map(row=>`<label class="bulk-row ${row.duplicate?'bulk-duplicate':''}"><input type="checkbox" data-bulk-index="${row.index}" ${row.valid&&!row.duplicate?'checked':''} ${row.valid?'':'disabled'}><span><strong>${esc(row.text)}</strong><small>${esc(row.project||'پروژه نامشخص')} • ${money(row.amount)} • ${esc(row.date)}${row.dateExplicit?'':' (تاریخ ذکر نشد)'} • ${row.kind==='income'?'دریافت':'پرداخت'}</small>${row.duplicate?'<em>مشابه ردیف ثبت‌شده یا ردیف دیگر؛ فقط با انتخاب شما ثبت می‌شود</em>':''}${!row.valid?'<em>پروژه یا مبلغ یا نوع عملیات مشخص نیست؛ این ردیف ثبت نمی‌شود</em>':''}</span></label>`).join('')}<button class="btn primary full-action" onclick="saveBulkCash()">ثبت ردیف‌های انتخاب‌شده</button>`}
function saveBulkCash(){const rows=window.bulkCashDraft||[],selected=[...document.querySelectorAll('#bulkReview input[data-bulk-index]:checked')].map(x=>rows[Number(x.dataset.bulkIndex)]).filter(x=>x?.valid);if(!selected.length)return toast('هیچ ردیف معتبری انتخاب نشده است');let count=0;for(const row of selected){let project=db.projects.find(x=>normalizedProjectName(x.name)===normalizedProjectName(row.project));if(!project){project={id:uid(),name:row.project,client:'ثبت نشده',location:'',budget:0,progress:0,status:'فعال',start:row.date,completeness:'draft'};db.projects.push(project)}if(row.category&&!db.categories.includes(row.category))db.categories.push(row.category);const id=uid();db.transactions.push({id,project:project.name,party:row.party||row.category,category:row.category,amount:row.amount,date:row.date,dateSource:row.dateExplicit?'explicit':'default',kind:row.kind,note:row.text,status:'ثبت اولیه',source:'bulk'});count++}save();document.getElementById('bulkCashModal')?.remove();window.bulkCashDraft=null;render();toast(`${fa(count)} ردیف ثبت شد؛ پیوست‌ها را بعداً اضافه کن`)}
