function openContractBranding(){document.getElementById('contractBrandingModal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="contractBrandingModal"><div class="dialog"><div class="dialog-head"><h2>سربرگ قرارداد</h2><button class="close" onclick="document.getElementById('contractBrandingModal').remove()">×</button></div><p>تصویر سربرگ خودت را اضافه کن تا بالای نسخه چاپی بیاید. فعلاً هیچ تصویری به‌جای سربرگ واقعی گذاشته نشده است.</p>${field('عنوان سربرگ',`<input id="brandTitle" value="${esc(db.contractBrandName||'زون دیزاین')}">`)}${field('تصویر سربرگ (PNG یا JPEG)',`<input id="brandImage" type="file" accept="image/png,image/jpeg">`)}<button class="btn primary" onclick="saveContractBranding()">ذخیره سربرگ</button></div></div>`)}
async function saveContractBranding(){const file=document.getElementById('brandImage')?.files?.[0];if(file){if(!['image/png','image/jpeg'].includes(file.type))return toast('فقط PNG یا JPEG انتخاب کن');try{const img=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,1200/img.width);canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.7);if(data.length>500000)return toast('تصویر سربرگ بزرگ است؛ نسخه کوچک‌تر انتخاب کن');db.contractLetterhead=data}catch{return toast('خواندن تصویر سربرگ ممکن نشد')}}db.contractBrandName=v('brandTitle')||'زون دیزاین';try{save()}catch{return toast('فضای ذخیره این دستگاه پر شده است')};document.getElementById('contractBrandingModal')?.remove();toast('سربرگ برای چاپ قراردادها ذخیره شد')}
const v36PrintContractDraftBase=printContractDraft;
printContractDraft=function(id){const c=db.contracts.find(x=>Number(x.id)===Number(id));if(!c)return toast('قرارداد پیدا نشد');if(c.templateKey==='management')return printManagementContract(c);const open=window.open;let printWindow;try{window.open=function(...args){printWindow=open.apply(window,args);return printWindow};v36PrintContractDraftBase(id)}finally{window.open=open}if(!printWindow)return;const body=printWindow.document.body;if(!body)return;const f=c.fields||{},section=printWindow.document.createElement('section');const detail=[f.start&&`تاریخ شروع: ${f.start}`,f.duration&&`مدت: ${f.duration} روز`,f.delayContractor&&`خسارت تأخیر منتسب به پیمانکار: ${f.delayContractor} تومان در روز`,f.delayEmployer&&`خسارت تأخیر منتسب به واگذارنده: ${f.delayEmployer} تومان در روز`,f.delayTerms&&`شرایط محاسبه: ${f.delayTerms}`].filter(Boolean).join('\n');section.innerHTML=`<h3>مدت و خسارت تأخیر توافقی</h3><p>${esc(detail||'تعیین نشده؛ پیش از امضا تکمیل شود')}</p>`;body.querySelector('.sign')?.before(section);if(db.contractLetterhead){const img=printWindow.document.createElement('img');img.src=db.contractLetterhead;img.alt='سربرگ';img.style='display:block;width:100%;max-height:125px;object-fit:contain;object-position:right;margin-bottom:14px';body.prepend(img)}else if(db.contractBrandName){const header=printWindow.document.createElement('p');header.textContent=db.contractBrandName;body.prepend(header)}};
const v36ProjectDetailBase=projectDetail;
projectDetail=function(){let html=v36ProjectDetailBase();const p=db.projects.find(x=>Number(x.id)===Number(selectedProjectId));if(!p)return html;const management=db.contracts.filter(x=>x.project===p.name&&x.templateKey==='management');const area=`<section class="detail-section contract-panel"><div class="section-inline"><h3>مدیریت پیمان با کارفرما</h3><button class="btn primary" onclick="openManagementContract(${Number(p.id)})">＋ تنظیم قرارداد درصدی</button></div>${management.map(c=>`<div class="contract-item"><strong>${esc(c.title)}</strong><small>${esc(c.party)} • ${esc(c.fields?.feePercent||'درصد تعیین نشده')}٪ از مبنای هزینه توافقی</small><button class="btn" onclick="openManagementContract(${Number(p.id)},${Number(c.id)})">ویرایش</button><button class="btn" onclick="printContractDraft(${Number(c.id)})">چاپ / PDF</button></div>`).join('')||'<p class="contract-empty">هنوز قراردادی با کارفرما ثبت نشده است.</p>'}</section>`;return html.replace('<section class="detail-section"><h3>گردش مالی</h3>',area+'<section class="detail-section"><h3>گردش مالی</h3>')};
function openManagementContract(projectId,contractId=0){const p=db.projects.find(x=>Number(x.id)===Number(projectId)),c=db.contracts.find(x=>Number(x.id)===Number(contractId)&&x.templateKey==='management');if(!p)return;const f=c?.fields||{},issuer=db.contractIssuer||{};document.getElementById('managementContractModal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="managementContractModal"><div class="dialog contract-builder"><div class="dialog-head"><h2>قرارداد مدیریت پیمان • ${esc(p.name)}</h2><button class="close" onclick="document.getElementById('managementContractModal').remove()">×</button></div><p class="contract-disclaimer">نمونه قابل ویرایش برای توافق با کارفرما؛ درصد و مبنای محاسبه را پیش از امضا دقیق کنید. این پیش‌نویس جای بررسی حقوقی قرارداد واقعی را نمی‌گیرد.</p><div class="form-grid">${field('نام کارفرما',`<input id="mgClient" value="${esc(f.client||((p.client==='ثبت نشده')?'':p.client)||'')}">`)}${field('کد ملی یا شناسه کارفرما',`<input id="mgClientNational" inputmode="numeric" value="${esc(f.clientNational||'')}">`)}${field('نشانی و تماس کارفرما',`<input id="mgClientAddress" value="${esc(f.clientAddress||'')}">`)}${field('نام مدیر پیمان',`<input id="mgManager" value="${esc(f.manager||issuer.name||'')}">`)}${field('کد ملی مدیر پیمان',`<input id="mgManagerNational" inputmode="numeric" value="${esc(f.managerNational||issuer.nationalId||'')}">`)}${field('نشانی و تماس مدیر پیمان',`<input id="mgManagerAddress" value="${esc(f.managerAddress||issuer.address||'')}">`)}${field('تاریخ قرارداد شمسی',`<input id="mgDate" value="${esc(c?.date||todayFa())}">`)}${field('تاریخ شروع شمسی',`<input id="mgStart" value="${esc(f.start||'')}">`)}${field('مدت مدیریت (روز)',`<input id="mgDuration" inputmode="numeric" value="${esc(f.duration||'')}">`)}${field('درصد حق‌الزحمه مدیریت پیمان',`<input id="mgPercent" inputmode="decimal" value="${esc(f.feePercent||'')}" placeholder="مثلاً ۱۰؛ فقط در صورت توافق">`)}${field('هزینه‌های مشمول درصد',`<textarea id="mgBasis">${esc(f.basis||'هزینه‌های مستند و تأییدشده پروژه شامل قراردادهای اجرایی، خرید مصالح، دستمزدها و حمل، طبق صورت‌حساب و مدارک پیوست. خرید مستقیم کارفرما فقط اگر صریحاً توافق شده باشد مشمول است.')}</textarea>`,'full')}${field('هزینه‌های مستثنی و جلوگیری از محاسبه دوباره',`<textarea id="mgExclusions">${esc(f.exclusions||'حق‌الزحمه مدیریت پیمان، خسارت‌ها، هزینه‌های خارج از پروژه و مبالغ برگشتی از مبنای درصد مستثنی‌اند؛ مالیات و خرید مستقیم کارفرما را طرفین صریحاً تعیین کنند.')}</textarea>`,'full')}${field('حدود اختیار، تصویب خرید و گزارش‌دهی',`<textarea id="mgAuthority">${esc(f.authority||'مدیر پیمان برای خرید و انعقاد قرارداد در سقف اختیار کتبی توافق‌شده اقدام می‌کند و اسناد هزینه و گزارش پیشرفت را در دوره‌های توافقی به کارفرما ارائه می‌دهد. تصمیم‌های خارج از حدود اختیار نیازمند تأیید کتبی است.')}</textarea>`,'full')}${field('دوره صورت‌حساب و مهلت پرداخت',`<textarea id="mgPayment">${esc(f.payment||'هزینه‌های تأییدشده و حق‌الزحمه درصدی مربوط، در صورت‌حساب دوره‌ای جداگانه محاسبه و در مهلت توافقی پرداخت می‌شوند.')}</textarea>`,'full')}${field('تأخیر منتسب به مدیر پیمان (تومان در روز)',`<input id="mgDelayManager" data-money inputmode="numeric" value="${esc(f.delayManager||'')}">`)}${field('تأخیر کارفرما در پرداخت یا تحویل محل (تومان در روز)',`<input id="mgDelayClient" data-money inputmode="numeric" value="${esc(f.delayClient||'')}">`)}${field('موارد تمدید مدت و مبنای محاسبه خسارت',`<textarea id="mgDelayTerms">${esc(f.delayTerms||'تأخیر باید مستند و به طرف مقابل اعلام شود؛ تأخیر ناشی از تغییر دستورکار یا عدم تأمین منابع کارفرما با صورت‌جلسه در مدت قرارداد لحاظ شود.')}</textarea>`,'full')}${field('فسخ، تحویل اسناد و رسیدگی به اختلاف',`<textarea id="mgDispute">${esc(f.dispute||'در خاتمه، مدارک خرید، قراردادها، صورت‌حساب‌ها و کارهای انجام‌شده با صورت‌جلسه تحویل و مطالبات تا تاریخ خاتمه محاسبه می‌شود. مرجع حل اختلاف با توافق کتبی مشخص شود.')}</textarea>`,'full')}</div><div class="contract-actions"><button class="btn" onclick="openContractBranding()">＋ افزودن سربرگ</button><button class="btn primary" onclick="saveManagementContract(${Number(projectId)},${Number(contractId)})">ذخیره پیش‌نویس</button></div></div></div>`)}
function saveManagementContract(projectId,contractId=0){const p=db.projects.find(x=>Number(x.id)===Number(projectId)),client=v('mgClient'),manager=v('mgManager'),percent=PeymanyarContracts.number(v('mgPercent'));if(!p||!client||!manager)return toast('نام کارفرما و مدیر پیمان را وارد کن');if(!v('mgBasis'))return toast('مبنای هزینه‌های مشمول درصد را تعیین کن');if(percent<=0||percent>100)return toast('درصد توافقی را بین صفر و صد وارد کن');const fields={client,clientNational:v('mgClientNational'),clientAddress:v('mgClientAddress'),manager,managerNational:v('mgManagerNational'),managerAddress:v('mgManagerAddress'),start:v('mgStart'),duration:v('mgDuration'),feePercent:percent,basis:v('mgBasis'),exclusions:v('mgExclusions'),authority:v('mgAuthority'),payment:v('mgPayment'),delayManager:v('mgDelayManager'),delayClient:v('mgDelayClient'),delayTerms:v('mgDelayTerms'),dispute:v('mgDispute')};let c=db.contracts.find(x=>Number(x.id)===Number(contractId)&&x.templateKey==='management'&&x.status==='پیش‌نویس');if(!c){c={id:uid(),templateKey:'management',status:'پیش‌نویس'};db.contracts.push(c)}Object.assign(c,{title:'قرارداد مدیریت پیمان '+p.name,project:p.name,party:client,amount:0,date:v('mgDate')||todayFa(),fields});p.client=client;db.contractIssuer={...(db.contractIssuer||{}),name:manager,nationalId:fields.managerNational,address:fields.managerAddress};save();document.getElementById('managementContractModal')?.remove();render();toast('پیش‌نویس مدیریت پیمان ذخیره شد؛ درصد بر هزینه‌های واقعی تأییدشده محاسبه می‌شود')}
function printManagementContract(c){const w=window.open('','_blank');if(!w)return toast('اجازه پنجره چاپ را فعال کن');const f=c.fields||{},row=(title,value)=>`<section><h3>${esc(title)}</h3><p>${esc(value||'—')}</p></section>`;w.document.write(`<html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>${esc(c.title)}</title><style>body{font-family:Tahoma,Arial,sans-serif;line-height:1.9;max-width:850px;margin:auto;padding:25px;color:#222}h1{text-align:center}h3{margin:16px 0 2px;font-size:16px}p{white-space:pre-wrap;margin:0}section{break-inside:avoid}.sign{display:flex;justify-content:space-between;margin-top:65px}@page{size:A4;margin:17mm}</style></head><body>${db.contractLetterhead?`<img alt="سربرگ" style="width:100%;max-height:125px;object-fit:contain;object-position:right" src="${db.contractLetterhead}">`:`<p>${esc(db.contractBrandName||'')}</p>`}<h1>${esc(c.title)}</h1><p>پیش‌نویس نمونه قابل بررسی و تکمیل پیش از امضا</p>${row('طرفین',`کارفرما: ${f.client} | شناسه: ${f.clientNational||'—'} | نشانی و تماس: ${f.clientAddress||'—'}\nمدیر پیمان: ${f.manager} | کد ملی: ${f.managerNational||'—'} | نشانی و تماس: ${f.managerAddress||'—'}`)}${row('موضوع و پروژه',`مدیریت و هماهنگی اجرای پروژه ${c.project}، خریدهای مصوب، رسیدگی به پیمانکاران و ارائه اسناد و گزارش‌های توافق‌شده؛ بدون تعهد اجرای مستقیم عملیات مگر با قرارداد جداگانه.`)}${row('تاریخ و مدت',`تاریخ قرارداد: ${c.date} | شروع: ${f.start||'تعیین نشده'} | مدت: ${f.duration||'تعیین نشده'} روز`)}${row('حق‌الزحمه و مبنای محاسبه',`${fa(f.feePercent)} درصد از مجموع هزینه‌های مشمول و تأییدشده پروژه؛ مبلغ نهایی با هزینه واقعی مستند محاسبه می‌شود.\nهزینه‌های مشمول: ${f.basis}\nهزینه‌های مستثنی: ${f.exclusions}`)}${row('حدود اختیار و گزارش‌دهی',f.authority)}${row('صورت‌حساب و پرداخت',f.payment)}${row('تأخیر دو طرف',`مدیر پیمان: ${f.delayManager||'تعیین نشده'} تومان در روز تأخیر منتسب؛ کارفرما: ${f.delayClient||'تعیین نشده'} تومان در روز تأخیر منتسب.\n${f.delayTerms||''}`)}${row('تغییر، خاتمه و اختلاف',f.dispute)}${row('ایمنی، کارکنان و اسناد',PeymanyarContracts.commonClauses.find(x=>x.title.includes('ایمنی'))?.body)}<div class="sign"><div>امضا و تاریخ کارفرما:<br>....................</div><div>امضا و تاریخ مدیر پیمان:<br>....................</div></div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}

// v37: edit archived document metadata and its linked financial row; image/OCR pipeline stays unchanged.
const v37DocumentInfoCardBase=documentInfoCard;
documentInfoCard=function(doc){const card=v37DocumentInfoCardBase(doc);return card.replace(`<button type="button" class="btn primary" onclick="viewDocument(${Number(doc.id)})">`, `<button type="button" class="btn" onclick="openRecordEditor('document',${Number(doc.id)})">✎ ویرایش همه مشخصات</button><button type="button" class="btn primary" onclick="viewDocument(${Number(doc.id)})">`)};
const v37TransactionReportTableBase=transactionReportTable;
transactionReportTable=function(rows){return v37TransactionReportTableBase(rows).replace(/onclick="openAmountEditor\('transaction',(\d+)\)"/g,(_all,id)=>`onclick="openRecordEditor('transaction',${id})"`).replaceAll('✎ اصلاح مبلغ','✎ ویرایش مشخصات')};
const v37ViewDocumentBase=viewDocument;
viewDocument=async function(id){await v37ViewDocumentBase(id);const viewer=document.getElementById('docViewer'),doc=db.documents.find(x=>Number(x.id)===Number(id));if(viewer&&doc){const head=viewer.querySelector('.viewer-head');head?.insertAdjacentHTML('beforeend',`<button type="button" class="btn" onclick="closeViewer();openRecordEditor('document',${Number(id)})">✎ ویرایش مشخصات</button>`)}};
function openRecordEditor(kind,id){const transaction=kind==='transaction'?db.transactions.find(x=>Number(x.id)===Number(id)):db.transactions.find(x=>Number(x.documentId)===Number(id));const doc=kind==='document'?db.documents.find(x=>Number(x.id)===Number(id)):db.documents.find(x=>Number(x.id)===Number(transaction?.documentId));const record=doc||transaction;if(!record)return toast('مورد انتخاب‌شده پیدا نشد');document.getElementById('recordEditor')?.remove();const isFinancial=!!transaction,party=doc?.party||transaction?.party||'',category=doc?.category||transaction?.category||'',note=doc?.note||transaction?.note||'';document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="recordEditor"><div class="dialog smart-upload-dialog"><div class="dialog-head"><h2>ویرایش کامل ${doc?'سند':'ثبت مالی'}</h2><button class="close" onclick="document.getElementById('recordEditor').remove()">×</button></div><p>تصویر اصلی و متن تشخیص‌داده‌شده تغییر نمی‌کند. تغییرهای این فرم در سند و ردیف مالیِ متصل به آن ثبت می‌شود.</p><div class="form-grid">${doc?field('عنوان سند',`<input id="reTitle" value="${esc(doc.title||doc.name||'')}">`):''}${doc?field('نوع سند',`<input id="reType" value="${esc(doc.docType||'')}">`):''}${field('پروژه',`<input id="reProject" list="reProjects" value="${esc(record.project==='بدون پروژه'?'':record.project||'')}" placeholder="نام پروژه را بنویس"><datalist id="reProjects">${db.projects.map(x=>`<option value="${esc(x.name)}"></option>`).join('')}</datalist>`)}${field('دسته‌بندی / بابت',`<input id="reCategory" list="reCategories" value="${esc(category)}" placeholder="مثلاً خرید مصالح"><datalist id="reCategories">${db.categories.map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist>`)}${field('طرف حساب یا گیرنده',`<input id="reParty" list="rePeople" value="${esc(party)}" placeholder="نام شخص یا شرکت"><datalist id="rePeople">${db.people.map(x=>`<option value="${esc(x.name)}"></option>`).join('')}</datalist>`)}${field('مبلغ به تومان',`<input id="reAmount" data-money inputmode="numeric" value="${record.amount?fa(record.amount):''}" placeholder="اگر مبلغ ندارد خالی بگذار">`)}${field('تاریخ شمسی',`<input id="reDate" inputmode="numeric" value="${esc(record.date||todayFa())}" placeholder="۱۴۰۵/۰۷/۰۱">`)}${field('ساعت',`<input id="reTime" value="${esc(doc?.time||transaction?.time||'')}" placeholder="مثلاً ۱۴:۳۰">`)}${isFinancial?field('نوع ثبت مالی',`<select id="reKind"><option value="expense" ${transaction.kind==='expense'?'selected':''}>پرداخت / هزینه</option><option value="income" ${transaction.kind==='income'?'selected':''}>دریافت / واریزی</option></select>`):''}${doc?field('مبدأ',`<input id="reOrigin" value="${esc(doc.origin||'')}">`):''}${doc?field('مقصد',`<input id="reDestination" value="${esc(doc.destination||'')}">`):''}${field('شماره پیگیری',`<input id="reTracking" inputmode="numeric" value="${esc(doc?.tracking||transaction?.tracking||'')}">`)}${doc?field('بانک مبدأ',`<input id="reOriginBank" value="${esc(doc.originBank||'')}">`):''}${doc?field('بانک مقصد',`<input id="reDestinationBank" value="${esc(doc.destinationBank||'')}">`):''}${field('شرح / بابت پرداخت',`<textarea id="reNote" rows="3">${esc(note)}</textarea>`,'full')}${doc?field('توضیح تکمیلی سند',`<textarea id="reDescription" rows="2">${esc(doc.description||'')}</textarea>`,'full'):''}</div><div class="dialog-actions"><button class="btn primary" onclick="saveRecordEditor('${kind}',${Number(id)})">ذخیره همه تغییرات</button><button class="btn" onclick="document.getElementById('recordEditor').remove()">انصراف</button></div></div></div>`)}
function saveRecordEditor(kind,id){const tx=kind==='transaction'?db.transactions.find(x=>Number(x.id)===Number(id)):db.transactions.find(x=>Number(x.documentId)===Number(id)),doc=kind==='document'?db.documents.find(x=>Number(x.id)===Number(id)):db.documents.find(x=>Number(x.id)===Number(tx?.documentId));if(!doc&&!tx)return toast('مورد پیدا نشد');const project=v('reProject'),date=normalizeDateValue(v('reDate')),amount=v('reAmount')?n('reAmount'):0,category=v('reCategory'),party=v('reParty'),note=v('reNote'),time=v('reTime'),tracking=v('reTracking');if(!project||!category||!date)return toast('پروژه، بابت و تاریخ معتبر را وارد کن');if(!/^(1[34]\d{2})\/(0[1-9]|1[0-2])\/(0[1-9]|[12]\d|3[01])$/.test(date))return toast('تاریخ شمسی معتبر وارد کن');if(v('reAmount')&&!amount)return toast('مبلغ معتبر به تومان وارد کن');if(!db.projects.some(x=>x.name===project))db.projects.push({id:uid(),name:project,client:'ثبت نشده',location:'',budget:0,progress:0,status:'فعال',start:date,completeness:'draft'});if(!db.categories.includes(category))db.categories.push(category);if(doc){Object.assign(doc,{title:v('reTitle')||doc.name,docType:v('reType')||'سایر',project,date:date.replace(/[0-9]/g,d=>'۰۱۲۳۴۵۶۷۸۹'[Number(d)]),amount,category,party,origin:v('reOrigin'),destination:v('reDestination')||party,originBank:v('reOriginBank'),destinationBank:v('reDestinationBank'),time,tracking,note,description:v('reDescription'),status:'کامل'});if(!party&&/قرارداد/.test(doc.docType))doc.status='نیازمند تکمیل';const linkedContract=db.contracts.find(c=>Number(c.documentId)===Number(doc.id));if(linkedContract)Object.assign(linkedContract,{title:doc.title,project,date,party,amount})}if(tx)Object.assign(tx,{project,date:date.replace(/[0-9]/g,d=>'۰۱۲۳۴۵۶۷۸۹'[Number(d)]),amount,category,party:party||category,note,time,tracking,kind:v('reKind')||tx.kind});save();document.getElementById('recordEditor')?.remove();render();toast('اطلاعات سند و ردیف مالی مرتبط اصلاح شد')}

// v38: one editor from every visible financial record, and completion only after verification.
const v38ActivityRowBase=activityRow;
activityRow=function(row){return `<div class="activity-item"><div class="activity-icon">${row.kind==='income'?'↙':'↗'}</div><div><strong>${esc(row.category||'ثبت مالی')}</strong><small>${esc(row.project||'')} • ${esc(row.party||'')} • ${esc(row.date||'')}</small><button class="edit-amount" onclick="openRecordEditor('transaction',${Number(row.id)})">✎ ویرایش مشخصات</button></div><span class="amount ${row.kind==='expense'?'out':''}">${row.kind==='income'?'+':'−'} ${money(row.amount)}</span></div>`};
function taskRecord(task){const id=String(task?.entityId??'');if(task?.type==='document.review')return db.documents.find(x=>String(x.id)===id);if(task?.type?.startsWith('transaction.'))return db.transactions.find(x=>String(x.id)===id);if(task?.type?.startsWith('person.'))return db.people.find(x=>String(x.id)===id);if(task?.type==='project.details')return db.projects.find(x=>String(x.id)===id);if(task?.type==='daily.project')return db.daily.find(x=>String(x.id)===id);return null}
function taskSatisfied(task){const record=taskRecord(task);if(!record)return false;switch(task.type){case 'transaction.attachment':return transactionHasDocument(record);case 'transaction.project':return !!(record.project&&record.project!=='بدون پروژه'&&db.projects.some(x=>x.name===record.project));case 'transaction.amount':return Number(record.amount)>0;case 'document.review':return !!(record.project&&record.project!=='بدون پروژه'&&record.category&&record.category!=='نیازمند تکمیل'&&record.date&&record.title);case 'person.details':return !!(record.nationalId&&record.phone&&record.address);case 'person.role':return !!(record.role&&!['طرف حساب','تخصص ثبت نشده','نامشخص'].includes(record.role));case 'person.contract':return signedContractFor(record);case 'project.details':return !!(record.client&&record.client!=='ثبت نشده'&&record.location);case 'daily.project':return !!(record.project&&record.project!=='بدون پروژه'&&db.projects.some(x=>x.name===record.project));default:return false}}
function completionTaskHint(task){return({'transaction.attachment':'تصویر رسید را به همین ثبت مالی پیوست کن.','transaction.project':'پروژه این ثبت مالی را مشخص کن.','transaction.amount':'مبلغ این ثبت مالی را وارد کن.','document.review':'پروژه، بابت، تاریخ و عنوان سند را بررسی کن.','person.details':'کد ملی، تلفن و نشانی را کامل کن.','person.role':'تخصص یا نقش را ثبت کن.','person.contract':'قرارداد امضاشده را بارگذاری کن.','project.details':'کارفرما و موقعیت پروژه را کامل کن.','daily.project':'پروژه گزارش روزانه را مشخص کن.'})[task.type]||'جزئیات این مورد را بررسی کن.'}
completionTaskRow=function(task){const complete=taskSatisfied(task),id=esc(task.id),attachment=task.type==='transaction.attachment',row=taskRecord(task),title=attachment&&row?`رسید ${row.kind==='income'?'دریافت':'پرداخت'} ${money(row.amount)}${row.party?' • '+row.party:''}`:task.title;return `<article class="completion-row"><span class="completion-kind">${attachment?'📎':'◌'}</span><div><strong>${esc(title)}</strong><small>${esc([row?.project||task.project,row?.date||task.eventDate].filter(Boolean).join(' • ')||'ثبت اولیه')}</small><small>${esc(complete?'اطلاعات لازم تکمیل شده است.':completionTaskHint(task))}</small></div>${attachment&&row?`<button onclick="openCompletionRecordEditor('transaction',${Number(row.id)})">ویرایش اطلاعات</button>`:''}<button onclick="completionAction('${id}')">${attachment?'افزودن سند':complete?'مشاهده':'تکمیل مشخصات'}</button>${complete?`<button class="completion-done" onclick="resolveCompletionTask('${id}')">انجام شد</button>`:''}</article>`};
completionAction=function(id){const task=completionOpen().find(x=>String(x.id)===String(id));if(!task)return;const record=taskRecord(task);document.getElementById('completionInbox')?.remove();if(task.type==='transaction.attachment')return attachTransactionDocument(task.entityId);if(['transaction.project','transaction.amount'].includes(task.type)&&record)return openRecordEditor('transaction',Number(record.id));if(task.type==='document.review'&&record)return openRecordEditor('document',Number(record.id));if(task.type==='person.details'&&record)return openPersonIdentity(Number(record.id));if(task.type==='person.role'&&record){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="roleCompletion"><div class="dialog"><div class="dialog-head"><h2>تخصص ${esc(record.name)}</h2><button class="close" onclick="document.getElementById('roleCompletion').remove()">×</button></div>${field('تخصص / نقش',`<input id="roleCompletionInput" value="${esc(record.role==='تخصص ثبت نشده'?'':record.role||'')}">`)}<button class="btn primary" onclick="saveCompletedRole('${esc(task.id)}')">ذخیره تخصص</button></div></div>`);return}if(task.type==='person.contract'&&record)return openPerson(Number(record.id));if(task.type==='project.details'&&record)return openProjectCompletionEditor(Number(record.id));if(task.type==='daily.project'&&record)return openDailyCompletionEditor(Number(record.id));toast('مورد انتخاب‌شده پیدا نشد')};
function openCompletionRecordEditor(kind,id){document.getElementById('completionInbox')?.remove();openRecordEditor(kind,id)}
resolveCompletionTask=function(id){const task=completionOpen().find(x=>String(x.id)===String(id));if(!task)return;if(!taskSatisfied(task))return toast(completionTaskHint(task));const stored=db.completionTasks.find(x=>String(x.id)===String(task.id));if(stored){stored.status='done';stored.resolvedAt=new Date().toISOString();save()}document.getElementById('completionInbox')?.remove();toast('اطلاعات بررسی و تکمیل شد');render();if(completionOpen().length)setTimeout(openCompletionInbox,50)};
function openProjectCompletionEditor(id){const p=db.projects.find(x=>Number(x.id)===Number(id));if(!p)return;document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="projectCompletionEditor"><div class="dialog"><div class="dialog-head"><h2>تکمیل پروژه ${esc(p.name)}</h2><button class="close" onclick="document.getElementById('projectCompletionEditor').remove()">×</button></div>${field('کارفرما',`<input id="completeClient" value="${esc(p.client==='ثبت نشده'?'':p.client||'')}">`)}${field('موقعیت پروژه',`<input id="completeLocation" value="${esc(p.location||'')}">`)}<button class="btn primary" onclick="saveProjectCompletion(${Number(id)})">ذخیره مشخصات</button></div></div>`)}
function saveProjectCompletion(id){const p=db.projects.find(x=>Number(x.id)===Number(id));if(!p||!v('completeClient')||!v('completeLocation'))return toast('نام کارفرما و موقعیت را وارد کن');p.client=v('completeClient');p.location=v('completeLocation');save();document.getElementById('projectCompletionEditor')?.remove();render();toast('مشخصات پروژه ذخیره شد؛ این مورد آماده تأیید است')}
function openDailyCompletionEditor(id){const d=db.daily.find(x=>Number(x.id)===Number(id));if(!d)return;document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="dailyCompletionEditor"><div class="dialog"><div class="dialog-head"><h2>تکمیل گزارش روزانه</h2><button class="close" onclick="document.getElementById('dailyCompletionEditor').remove()">×</button></div>${field('پروژه',`<input id="completeDailyProject" list="completeDailyProjects" value="${esc(d.project==='بدون پروژه'?'':d.project||'')}"><datalist id="completeDailyProjects">${db.projects.map(p=>`<option value="${esc(p.name)}"></option>`).join('')}</datalist>`)}<button class="btn primary" onclick="saveDailyCompletion(${Number(id)})">ذخیره پروژه</button></div></div>`)}
function saveDailyCompletion(id){const d=db.daily.find(x=>Number(x.id)===Number(id)),p=v('completeDailyProject');if(!d||!p)return toast('نام پروژه را وارد کن');if(!db.projects.some(x=>x.name===p))db.projects.push({id:uid(),name:p,client:'ثبت نشده',location:'',budget:0,progress:0,status:'فعال',start:d.date,completeness:'draft'});d.project=p;save();document.getElementById('dailyCompletionEditor')?.remove();render();toast('پروژه گزارش ذخیره شد؛ این مورد آماده تأیید است')}
const v38SaveCompletedRoleBase=saveCompletedRole;
saveCompletedRole=function(id){const role=v('roleCompletionInput');if(!role||['طرف حساب','تخصص ثبت نشده','نامشخص'].includes(role))return toast('تخصص واقعی را وارد کن تا این مورد تکمیل شود');return v38SaveCompletedRoleBase(id)};
const v38FinanceBase=finance;
finance=function(){return v38FinanceBase().replace('برای اصلاح هر مبلغ روی «اصلاح مبلغ» بزن','هر ثبت مالی را از همین صفحه باز کن و همه مشخصاتش را ویرایش کن')};
