// v43: send voice directly; an extra health request must not block transcription.
async function voiceTranscriptionRequest(endpoint,form){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),18000);try{const response=await fetch(`${endpoint}/transcribe`,{method:'POST',body:form,signal:controller.signal});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.detail||result.error||`HTTP ${response.status}`);return String(result.text||'').trim()}finally{clearTimeout(timer)}}
sendVoiceToAIReliable=async function(blob){if(!blob||blob.size<400)throw new Error('empty_audio');const input=document.getElementById('quickText');if(!input)throw new Error('input_missing');aiVoiceSending=true;setVoiceState('صدا ضبط شد؛ در حال تبدیل به متن…',true);const saved=(localStorage.getItem(AI_ENDPOINT_KEY)||'').replace(/\/$/,'');const endpoints=[...new Set([saved||DEFAULT_AI_ENDPOINT,DEFAULT_AI_ENDPOINT])];const form=new FormData();form.append('file',blob,`voice.${voiceFileExtension(blob.type)}`);try{let failure;for(const endpoint of endpoints){try{const recognized=await voiceTranscriptionRequest(endpoint,form);if(recognized){input.value=recognized;setVoiceState('متن آماده شد؛ در حال تحلیل فرمان…');setTimeout(parseQuick,100)}else setVoiceState('گفتاری تشخیص داده نشد؛ یک بار دیگر امتحان کن.');return}catch(error){failure=error;if(error?.name==='AbortError')failure=new Error('timeout');if(!/^(?:TypeError|AbortError)$/.test(error?.name||'')&&!/502|503|504|timeout/i.test(String(error?.message||'')))break}}throw failure}finally{aiVoiceSending=false}};
const v43VoiceBase=startVoice;
startVoice=async function(){const result=await v43VoiceBase();if(pcmVoiceRecording){clearTimeout(pcmVoiceAutoStop);pcmVoiceAutoStop=setTimeout(()=>{if(pcmVoiceRecording)stopPcmVoice()},12000)}return result};

// v44: a separate long dictation session for importing old petty-cash ledgers.
let bulkVoiceSession=null;
function bulkVoiceStatus(message){const node=document.getElementById('bulkVoiceStatus');if(node)node.textContent=message}
function bulkVoiceButtons(recording){const start=document.getElementById('bulkVoiceStart'),stop=document.getElementById('bulkVoiceStop');if(start)start.disabled=recording;if(stop)stop.disabled=!recording}
function closeBulkCash(){if(bulkVoiceSession?.recording){stopBulkVoice();bulkVoiceStatus('ضبط متوقف شد؛ برای جلوگیری از گم‌شدن متن، پس از تبدیل دوباره × را بزن.');return}if(bulkVoiceSession?.pending){bulkVoiceStatus('هنوز بخش‌هایی در حال تبدیل‌اند؛ پس از پایان می‌توانی ببندی.');return}bulkVoiceSession=null;document.getElementById('bulkCashModal')?.remove()}
const v44OpenBulkBase=openBulkCash;
openBulkCash=function(...args){v44OpenBulkBase(...args);const modal=document.getElementById('bulkCashModal');if(!modal)return;modal.setAttribute('onclick','if(event.target===this)closeBulkCash()');modal.querySelector('.dialog-head .close')?.setAttribute('onclick','closeBulkCash()');const old=modal.querySelector('.bulk-voice');old?.insertAdjacentHTML('afterend',`<div class="bulk-dictation"><strong>خواندن تنخواه‌های قدیمی</strong><p>پیوسته بخوان؛ هر ردیف را با «ردیف بعد» یا یک مکث جدا کن. صدا هر ۳۰ ثانیه جداگانه تبدیل می‌شود و تا ۱۰ دقیقه می‌توانی بخوانی. پیش از ثبت، نتیجه را بررسی کن.</p><div class="bulk-dictation-actions"><button type="button" class="btn primary" id="bulkVoiceStart" onclick="startBulkVoice()">🎙 شروع خواندن طولانی</button><button type="button" class="btn" id="bulkVoiceStop" onclick="stopBulkVoice()" disabled>■ پایان ضبط</button><button type="button" class="btn" id="bulkVoiceRetry" onclick="retryBulkVoice()" hidden>تلاش دوباره برای بخش ناموفق</button></div><small id="bulkVoiceStatus" role="status" aria-live="polite">ردیف‌ها بعد از تبدیل در کادر پایین می‌آیند؛ هیچ مبلغی خودکار ثبت نمی‌شود.</small></div>`);old?.remove()};
function appendBulkText(text){const input=document.querySelector('#bulkCashModal #quickText');if(!input||!text)return;const normalized=text.replace(/\s*(?:ردیف بعدی?|مورد بعدی?)\s*/g,'\n').trim();input.value=[input.value.trim(),normalized].filter(Boolean).join('\n');input.dispatchEvent(new Event('input',{bubbles:true}))}
async function transcribeBulkPart(blob){const saved=(localStorage.getItem(AI_ENDPOINT_KEY)||'').replace(/\/$/,'');const endpoints=[...new Set([saved||DEFAULT_AI_ENDPOINT,DEFAULT_AI_ENDPOINT])],form=new FormData();form.append('file',blob,'ledger.wav');let last;for(const endpoint of endpoints){try{return await voiceTranscriptionRequest(endpoint,form)}catch(e){last=e;if(e?.name!=='TypeError'&&e?.name!=='AbortError'&&!/502|503|504|timeout/i.test(String(e?.message||'')))break}}throw last}
function queueBulkPart(session,blob,part=++session.part){session.pending++;session.queue=session.queue.then(async()=>{try{const text=await transcribeBulkPart(blob);session.transcripts.set(part,text);const input=document.querySelector('#bulkCashModal #quickText');if(input)input.value=[session.baseText,...[...session.transcripts].sort((a,b)=>a[0]-b[0]).map(x=>x[1].replace(/\s*(?:ردیف بعدی?|مورد بعدی?)\s*/g,'\n'))].filter(Boolean).join('\n');bulkVoiceStatus(`بخش ${fa(part)} تبدیل شد${session.recording?'؛ ضبط ادامه دارد.':'؛ متن را بررسی کن.'}`)}catch(error){session.failed.push({part,blob});bulkVoiceStatus(`بخش ${fa(part)} تبدیل نشد؛ با «تلاش دوباره» آن را برگردان. ${voiceServiceError(error)}`);const retry=document.getElementById('bulkVoiceRetry');if(retry)retry.hidden=false}finally{session.pending--}});return session.queue}
function flushBulkVoice(session){if(!session.chunks.length)return;const samples=mergePcmChunks(session.chunks);session.chunks=[];if(samples.length<session.rate*.35)return;queueBulkPart(session,pcmToWav(downsamplePcm(samples,session.rate),16000))}
async function startBulkVoice(){if(bulkVoiceSession?.recording||bulkVoiceSession?.pending)return;if(!navigator.mediaDevices?.getUserMedia)return bulkVoiceStatus('میکروفن روی این مرورگر در دسترس نیست.');const AudioEngine=window.AudioContext||window.webkitAudioContext;if(!AudioEngine)return bulkVoiceStatus('برای ضبط طولانی، صفحه را در Safari یا Chrome باز کن.');let stream,context;try{stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});context=new AudioEngine();if(context.state==='suspended')await context.resume();const source=context.createMediaStreamSource(stream),processor=context.createScriptProcessor(4096,1,1),session={stream,context,source,processor,chunks:[],rate:context.sampleRate,part:0,pending:0,baseText:document.querySelector('#bulkCashModal #quickText')?.value||'',transcripts:new Map(),queue:Promise.resolve(),failed:[],recording:true,timer:null,limit:null};bulkVoiceSession=session;processor.onaudioprocess=e=>{e.outputBuffer.getChannelData(0).fill(0);if(session.recording)session.chunks.push(new Float32Array(e.inputBuffer.getChannelData(0)))};source.connect(processor);processor.connect(context.destination);session.timer=setInterval(()=>flushBulkVoice(session),30000);session.limit=setTimeout(()=>stopBulkVoice(),600000);bulkVoiceButtons(true);bulkVoiceStatus('در حال ضبط؛ هر ۳۰ ثانیه یک بخش تبدیل می‌شود. برای پایان دکمهٔ توقف را بزن.')}catch(error){stream?.getTracks().forEach(x=>x.stop());context?.close().catch(()=>{});bulkVoiceStatus(error?.name==='NotAllowedError'?'اجازهٔ میکروفن را فعال کن.':'میکروفن باز نشد؛ مرورگر را عوض کن.')}}
function stopBulkVoice(){const session=bulkVoiceSession;if(!session?.recording)return;session.recording=false;clearInterval(session.timer);clearTimeout(session.limit);flushBulkVoice(session);session.processor.onaudioprocess=null;session.source.disconnect();session.processor.disconnect();session.stream.getTracks().forEach(x=>x.stop());session.context.close().catch(()=>{});bulkVoiceButtons(false);bulkVoiceStatus('ضبط پایان یافت؛ بخش‌های باقیمانده در حال تبدیل‌اند.');session.queue.then(()=>{if(!session.failed.length)bulkVoiceStatus(`${fa(session.part)} بخش آماده شد؛ ردیف‌ها را بررسی کن، سپس «بررسی فهرست» را بزن.`)})}
function retryBulkVoice(){const session=bulkVoiceSession;if(!session?.failed.length)return;const failed=session.failed.splice(0);document.getElementById('bulkVoiceRetry').hidden=true;for(const item of failed)queueBulkPart(session,item.blob,item.part);bulkVoiceStatus('در حال تلاش دوباره برای بخش‌های ناموفق…')}
const v44ReviewBulkBase=reviewBulkCash;
reviewBulkCash=function(){if(bulkVoiceSession?.recording||bulkVoiceSession?.pending)return bulkVoiceStatus('ابتدا ضبط و تبدیل همهٔ بخش‌ها را تمام کن.');return v44ReviewBulkBase()};
const v44SaveBulkBase=saveBulkCash;
saveBulkCash=function(){if(bulkVoiceSession?.recording||bulkVoiceSession?.pending)return bulkVoiceStatus('تبدیل صدا هنوز تمام نشده است.');const result=v44SaveBulkBase();if(!document.getElementById('bulkCashModal'))bulkVoiceSession=null;return result};
const v44ParseQuickBase=parseQuick;
parseQuick=function(...args){if(document.getElementById('bulkCashModal')&&!document.getElementById('parsedResult'))return;return v44ParseQuickBase(...args)};
const v44SplitBulkBase=splitBulkCash;
splitBulkCash=function(text){return v44SplitBulkBase(String(text||'').replace(/\s*ردیف بعدی?\s*/g,'\n'))};

// v44: real dashboard shortcuts, clickable projects, and a working photo archive.
function openProjectGallery(){const photos=db.documents.filter(x=>x.docType==='تصویر پروژه'||/^image\//.test(x.type||'')||/\.(jpe?g|png|webp|heic)$/i.test(x.name||''));document.getElementById('projectGallery')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="projectGallery"><div class="dialog"><div class="dialog-head"><h2>عکس‌های پروژه‌ها</h2><button class="close" onclick="document.getElementById('projectGallery').remove()">×</button></div><div class="dashboard-gallery-list">${photos.map(x=>`<button class="btn" onclick="viewDocument(${Number(x.id)})">📷 ${esc(x.title||x.name)} · ${esc(x.project||'بدون پروژه')}</button>`).join('')||'<p>هنوز عکسی ثبت نشده است.</p>'}</div><button class="btn primary" onclick="document.getElementById('projectGallery').remove();openSmartUpload()">＋ افزودن عکس پروژه</button></div></div>`)}
const v44DashboardBase=dashboard;
dashboard=function(){let html=v44DashboardBase();const first=html.indexOf('<section class="grid-2"');if(first<0)return html;const after=html.indexOf('</main>',first);if(after<0)return html;const projects=`<section class="dashboard-projects"><div class="card-head"><h3>رفتن به پروژه</h3><button class="link-btn" onclick="go('projects')">همه پروژه‌ها</button></div><div class="dashboard-project-links">${db.projects.slice(0,6).map(p=>`<button class="btn" onclick="openProject(${Number(p.id)})">${esc(p.name)} <span>←</span></button>`).join('')||'<button class="btn" onclick="openForm(\'project\')">＋ ساخت اولین پروژه</button>'}</div></section>`;const shortcuts=`<section class="dashboard-shortcuts"><button onclick="go('projects')">▦<strong>پروژه‌ها</strong></button><button onclick="go('finance')">◉<strong>مالی</strong></button><button onclick="go('people')">♙<strong>افراد</strong></button><button onclick="go('daily')">☷<strong>گزارش‌ها</strong></button><button onclick="openProjectGallery()">▣<strong>عکس‌ها</strong></button><button onclick="openBulkCash()">≡<strong>تنخواه گروهی</strong></button></section>`;const recent=`<section class="card dashboard-recent"><div class="card-head"><h3>آخرین گردش مالی</h3><button class="link-btn" onclick="go('finance')">مشاهده همه</button></div><div class="activity">${db.transactions.slice(-3).reverse().map(activityRow).join('')||empty()}</div></section>`,ad='<aside class="dashboard-ad" aria-label="جایگاه معرفی خدمات">جایگاه معرفی خدمات و تبلیغات</aside>';html=html.slice(0,first)+shortcuts+projects+recent+ad+html.slice(after);return html};
